/* Tradução do Novo Mundo (edição de estudo), extraída do JW Library local. */
window.NWT = {"books": {"1": "Gênesis", "2": "Êxodo", "9": "1 Samuel", "11": "1 Reis", "14": "2 Crônicas", "19": "Salmo", "20": "Provérbios", "21": "Eclesiastes", "23": "Isaías", "24": "Jeremias", "33": "Miqueias", "40": "Mateus", "42": "Lucas", "45": "Romanos", "47": "2 Coríntios", "50": "Filipenses", "62": "1 João", "66": "Apocalipse"}, "verses": {"1:12:1": "E Jeová disse a Abrão: “Saia da sua terra e deixe os seus parentes e a casa do seu pai, e vá para a terra que lhe mostrarei.", "1:12:2": "Eu farei de você uma grande nação, o abençoarei e engrandecerei o seu nome, e você se tornará uma bênção.", "1:12:3": "Abençoarei os que o abençoarem e amaldiçoarei aquele que invocar o mal sobre você, e todas as famílias da terra certamente serão abençoadas por meio de você.”", "1:12:4": "Então Abrão foi, assim como Jeová lhe havia mandado, e Ló foi com ele. Abrão tinha 75 anos de idade quando saiu de Harã.", "1:12:5": "Abrão levou consigo sua esposa Sarai, Ló, filho de seu irmão, todos os bens que tinham acumulado e as pessoas que tinham adquirido em Harã, e eles partiram para a terra de Canaã. Quando chegaram à terra de Canaã,", "1:12:6": "Abrão atravessou aquela terra até o lugar chamado Siquém, perto das árvores grandes de Moré. (Naquele tempo, os cananeus moravam naquela terra.)", "1:12:7": "Jeová apareceu então a Abrão e disse: “Vou dar esta terra à sua descendência.” E ele construiu ali um altar a Jeová, que lhe havia aparecido.", "1:12:8": "Mais tarde, mudou-se dali para a região montanhosa ao leste de Betel e armou a sua tenda, com Betel ao oeste e Ai ao leste. Ali construiu um altar a Jeová e começou a invocar o nome de Jeová.", "1:12:9": "Depois, Abrão levantou acampamento e viajou na direção do Neguebe, acampando num lugar após outro.", "1:12:10": "Houve então uma fome naquela terra, e Abrão desceu em direção ao Egito para morar ali por um tempo, porque a fome era severa.", "1:12:11": "Quando estava para entrar no Egito, ele disse a Sarai, sua esposa: “Escute, por favor. Eu sei que você é uma mulher muito bonita.", "1:12:12": "Assim, quando os egípcios a virem, sem dúvida dirão: ‘Essa é a esposa dele.’ Então eles me matarão, mas deixarão você viva.", "1:12:13": "Diga, por favor, que é minha irmã, para que eu seja bem tratado por sua causa, e a minha vida seja poupada.”", "1:12:14": "Assim que Abrão entrou no Egito, os egípcios viram que a mulher era muito bonita.", "1:12:15": "E os príncipes de Faraó também a viram e começaram a elogiá-la diante de Faraó, de modo que a mulher foi levada para a casa de Faraó.", "1:12:16": "Ele tratou bem a Abrão por causa dela, e Abrão adquiriu ovelhas, bois, jumentos e jumentas, servos e servas, e camelos.", "1:12:17": "Então, Jeová infligiu terríveis pragas a Faraó e aos da sua casa, por causa de Sarai, esposa de Abrão.", "1:12:18": "Em vista disso, Faraó chamou Abrão e disse: “O que é isso que você me fez? Por que não me disse que ela era sua esposa?", "1:12:19": "Por que você disse: ‘Ela é minha irmã’? Eu estava para tomá-la como minha esposa! Aqui está a sua esposa. Tome-a e vá embora!”", "1:12:20": "Então Faraó deu ordens aos homens com respeito a Abrão, e eles o mandaram embora com sua esposa e tudo o que ele tinha.", "2:8:1": "Jeová disse então a Moisés: “Apresente-se a Faraó e diga-lhe: ‘Assim diz Jeová: “Deixe meu povo ir, para que me sirvam.", "2:8:2": "Se você continuar se recusando a deixá-los ir, atingirei todo o seu território com uma praga de rãs.", "2:8:3": "O rio Nilo ficará infestado de rãs; elas subirão e entrarão na sua casa e no seu quarto, estarão na sua cama, entrarão nas casas dos seus servos e estarão sobre o seu povo, nos seus fornos e nas suas amassadeiras.", "2:8:4": "As rãs virão sobre você, sobre o seu povo e sobre todos os seus servos.”’”", "2:8:5": "Mais tarde, Jeová disse a Moisés: “Diga a Arão: ‘Estenda a mão com o bastão sobre os rios, sobre os canais do Nilo e sobre os pântanos, e faça vir rãs sobre a terra do Egito.’”", "2:8:6": "Então Arão estendeu a mão sobre as águas do Egito, e as rãs começaram a vir e a cobrir a terra do Egito.", "2:8:7": "No entanto, os sacerdotes-magos fizeram a mesma coisa com as suas artes secretas: eles também fizeram vir rãs sobre a terra do Egito.", "2:8:8": "Então Faraó chamou Moisés e Arão, e disse: “Supliquem a Jeová que ele livre a mim e ao meu povo dessas rãs, visto que quero deixar o povo ir, para que ofereçam sacrifícios a Jeová.”", "2:8:9": "Moisés disse então a Faraó: “Cabe ao senhor a honra de decidir quando devo fazer súplicas para que o senhor, os seus servos, o seu povo e as suas casas fiquem livres das rãs. Elas ficarão somente no rio Nilo.”", "2:8:10": "Então ele disse: “Amanhã.” De modo que Moisés disse: “Será segundo a sua palavra, para que o senhor saiba que não há ninguém como Jeová, nosso Deus.", "2:8:11": "O senhor, as suas casas, os seus servos e o seu povo ficarão livres das rãs. Elas ficarão somente no Nilo.”", "2:8:12": "Assim, Moisés e Arão se retiraram da presença de Faraó, e Moisés suplicou a Jeová por causa das rãs que Ele havia enviado contra Faraó.", "2:8:13": "Então Jeová atendeu ao pedido de Moisés, e as rãs começaram a morrer nas casas, nos pátios e nos campos.", "2:8:14": "Elas foram ajuntadas em montões e mais montões, e a terra começou a cheirar mal.", "2:8:15": "Quando Faraó viu que houve alívio, endureceu o coração e não quis escutá-los, assim como Jeová havia falado.", "2:8:16": "Jeová disse então a Moisés: “Diga a Arão: ‘Estenda seu bastão e bata no pó da terra, e este se transformará em mosquitos em toda a terra do Egito.’”", "2:8:17": "E fizeram isso. Arão estendeu a mão com o seu bastão e bateu no pó da terra, e vieram mosquitos sobre homens e sobre animais. Todo o pó da terra se transformou em mosquitos em toda a terra do Egito.", "2:8:18": "Os sacerdotes-magos tentaram fazer o mesmo e produzir mosquitos com as suas artes secretas, mas não conseguiram. E vieram mosquitos sobre homens e sobre animais.", "2:8:19": "Então os sacerdotes-magos disseram a Faraó: “É o dedo de Deus!” Mas o coração de Faraó continuou endurecido, e ele não os escutou, assim como Jeová havia falado.", "2:8:20": "Então Jeová disse a Moisés: “Levante-se de manhã cedo e apresente-se a Faraó. Quando ele estiver saindo para ir ao rio, diga-lhe: ‘Assim disse Jeová: “Deixe meu povo ir, para que me sirvam.", "2:8:21": "Mas, se você não deixar meu povo ir, enviarei moscões contra você, seus servos, seu povo e suas casas; as casas do Egito ficarão cheias de moscões, e eles cobrirão o chão onde eles pisam.", "2:8:22": "Naquele dia certamente colocarei à parte a terra de Gósen, onde meu povo mora. Não haverá ali nenhum moscão; e assim você saberá que eu, Jeová, estou nesta terra.", "2:8:23": "Farei distinção entre o meu povo e o seu povo. Esse sinal ocorrerá amanhã.”’”", "2:8:24": "E Jeová fez isso. Grandes enxames de moscões começaram a invadir a casa de Faraó e as casas dos seus servos, e toda a terra do Egito. O país foi devastado por moscões.", "2:8:25": "Por fim, Faraó chamou Moisés e Arão, e disse: “Vão, ofereçam sacrifícios ao seu Deus aqui neste país.”", "2:8:26": "Mas Moisés disse: “Não convém fazer assim, pois o que queremos oferecer em sacrifício ao nosso Deus, Jeová, é detestável para os egípcios. Será que não seríamos apedrejados se oferecêssemos bem diante dos olhos dos egípcios um sacrifício que é detestável para eles?", "2:8:27": "Faremos uma viagem de três dias pelo deserto e ali ofereceremos sacrifícios a Jeová, nosso Deus, assim como ele nos disse.”", "2:8:28": "Faraó disse então: “Vou deixá-los ir, para que ofereçam sacrifícios a Jeová, seu Deus, no deserto. Somente não vão tão longe. Façam súplicas por mim.”", "2:8:29": "Então Moisés disse: “Agora vou me retirar da sua presença e farei súplicas a Jeová, e amanhã os moscões deixarão Faraó, seus servos e seu povo. Mas que Faraó não nos engane novamente, recusando-se a deixar o povo ir para oferecer sacrifícios a Jeová.”", "2:8:30": "Moisés se retirou então da presença de Faraó e fez súplicas a Jeová.", "2:8:31": "Assim, Jeová fez segundo a palavra de Moisés, e os moscões deixaram Faraó, seus servos e seu povo. Não sobrou nem sequer um moscão.", "2:8:32": "No entanto, Faraó novamente endureceu o coração e não deixou o povo ir.", "2:12:1": "Então Jeová disse a Moisés e a Arão na terra do Egito:", "2:12:2": "“Este mês será o começo dos meses; será o primeiro mês do ano para vocês.", "2:12:3": "Diga a toda a assembleia de Israel: ‘No dia dez deste mês, cada um deve pegar um cordeiro para a sua família, um cordeiro por casa.", "2:12:4": "Mas, se a família for pequena demais para comer o cordeiro, eles o comerão na sua casa junto com o seu vizinho mais próximo, de acordo com o número de pessoas. Ao fazer o cálculo, determinem quanto do cordeiro cada um comerá.", "2:12:5": "O animal deve ser sadio, macho de um ano. Podem escolher um carneirinho ou um cabrito.", "2:12:6": "Ele será guardado até o dia 14 deste mês, e toda a congregação de Israel o abaterá entre o pôr do sol e a noite.", "2:12:7": "Pegarão um pouco do sangue e o aspergirão nas laterais e na viga superior da entrada das casas em que o comerem.", "2:12:8": "“‘Naquela noite comerão a carne. Devem assá-la no fogo e comê-la com pães sem fermento e ervas amargas.", "2:12:9": "Não comam nada dessa carne nem crua nem cozida em água. Assem o animal inteiro no fogo, incluindo a cabeça, as pernas e as vísceras.", "2:12:10": "Não guardem nada para a manhã seguinte; mas, se sobrar alguma coisa na manhã seguinte, deve ser queimada no fogo.", "2:12:11": "É deste modo que devem comê-lo: com o cinto na cintura, as sandálias nos pés e o bastão na mão; e devem comê-lo às pressas. É a Páscoa de Jeová.", "2:12:12": "Pois naquela noite passarei pela terra do Egito e matarei todo primogênito na terra do Egito, desde homens até animais; e executarei o julgamento contra todos os deuses do Egito. Eu sou Jeová.", "2:12:13": "O sangue servirá de sinal para vocês nas casas em que estiverem; eu verei o sangue e passarei vocês por alto, e a praga não virá sobre vocês para destruí-los quando eu golpear a terra do Egito.", "2:12:14": "“‘Esse dia será para vocês um dia de recordação. Celebrem-no como festividade para Jeová por todas as suas gerações. Vocês devem celebrá-lo, pois é um decreto permanente.", "2:12:15": "Vocês devem comer pães sem fermento por sete dias. Sim, no primeiro dia devem retirar o fermento das suas casas, pois a pessoa que comer algo que tenha fermento, do primeiro ao sétimo dia, será eliminada de Israel.", "2:12:16": "No primeiro dia realizarão um santo congresso, e no sétimo dia outro santo congresso. Não se deve fazer nenhum trabalho nesses dias. Só poderão preparar o que cada um precisar para comer.", "2:12:17": "“‘Celebrem a Festividade dos Pães sem Fermento, pois nesse mesmo dia tirarei as suas multidões da terra do Egito. E guardem esse dia por todas as suas gerações. Isso é um decreto permanente.", "2:12:18": "Vocês devem comer pães sem fermento no primeiro mês, do anoitecer do dia 14 do mês até o anoitecer do dia 21 do mês.", "2:12:19": "Por sete dias não se deve achar nenhum fermento nas suas casas, porque a pessoa que comer algo que tenha fermento, seja estrangeiro, seja israelita de nascimento, será eliminada da assembleia de Israel.", "2:12:20": "Vocês não devem comer nada que tenha fermento. Em todas as casas devem comer pães sem fermento.’”", "2:12:21": "Moisés chamou prontamente todos os anciãos de Israel e lhes disse: “Escolham um animal do rebanho para cada família, e abatam o sacrifício pascoal.", "2:12:22": "Depois mergulhem um feixe de hissopo no sangue que estiver na bacia e marquem com o sangue a viga superior e as duas laterais da entrada da casa; e nenhum de vocês deve sair de casa até o amanhecer.", "2:12:23": "Então, quando Jeová passar para ferir os egípcios e vir o sangue na viga superior e nas laterais da entrada, Jeová certamente passará por alto a entrada e não permitirá que a praga da morte entre nas suas casas.", "2:12:24": "“Celebrem essa ocasião; isso é um decreto permanente para vocês e para os seus filhos.", "2:12:25": "Quando vocês entrarem na terra que Jeová lhes dará, assim como ele declarou, realizem essa celebração.", "2:12:26": "E, quando os seus filhos lhes perguntarem: ‘O que significa esta celebração para vocês?’,", "2:12:27": "respondam: ‘É o sacrifício da Páscoa para Jeová, que passou por alto as casas dos israelitas no Egito, quando feriu os egípcios, mas poupou as nossas casas.’” Então o povo se curvou e se prostrou.", "2:12:28": "E os israelitas fizeram assim como Jeová havia ordenado a Moisés e a Arão. Fizeram exatamente assim.", "2:12:29": "Então, à meia-noite, Jeová matou todo primogênito na terra do Egito, desde o primogênito do Faraó que estava sentado no trono até o primogênito do cativo que se achava na prisão, e todo primogênito dos animais.", "2:12:30": "Naquela noite, Faraó se levantou, assim como todos os seus servos e todos os outros egípcios, e houve um grande clamor entre os egípcios, pois não havia casa em que não houvesse um morto.", "2:12:31": "Ele chamou imediatamente Moisés e Arão à noite e disse: “Saiam já do meio do meu povo, tanto vocês como os outros israelitas. Vão e sirvam a Jeová, assim como disseram.", "2:12:32": "Levem também os seus rebanhos de ovelhas e de bois, assim como disseram. Mas abençoem também a mim.”", "2:12:33": "E os egípcios começaram a pressionar o povo para que saíssem depressa do país, pois diziam: “A bem dizer já estamos todos mortos!”", "2:12:34": "Então o povo levou a massa de pão ainda sem fermento, e sobre os ombros levou as amassadeiras embrulhadas em suas roupas.", "2:12:35": "Os israelitas fizeram o que Moisés lhes havia falado e pediram aos egípcios artigos de prata e de ouro, bem como roupas.", "2:12:36": "Jeová deu ao povo favor aos olhos dos egípcios, de modo que estes lhes deram o que pediram; e eles despojaram os egípcios.", "2:12:37": "Os israelitas partiram então de Ramessés para Sucote, cerca de 600.000 homens a pé, além das crianças.", "2:12:38": "E com eles foi também um grande número de não israelitas, bem como grandes rebanhos de ovelhas e de bois.", "2:12:39": "Com a massa que levaram do Egito, eles começaram a assar pães redondos sem fermento. Eram sem fermento porque eles haviam sido expulsos do Egito tão de repente que não tiveram tempo de preparar provisões para si.", "2:12:40": "O tempo de morada dos israelitas, que moraram no Egito, foi de 430 anos.", "2:12:41": "No dia em que se completaram os 430 anos, todas as multidões de Jeová saíram da terra do Egito.", "2:12:42": "Essa é uma noite em que celebrarão o fato de que Jeová os tirou da terra do Egito. É uma noite que todo o povo de Israel deve celebrar para Jeová, por todas as suas gerações.", "2:12:43": "Jeová disse a Moisés e a Arão: “Esta é a lei referente à Páscoa: nenhum estrangeiro pode comer da refeição pascoal.", "2:12:44": "Mas, se alguém tiver um escravo que foi comprado com dinheiro, este deve ser circuncidado. Só então ele poderá comer dela.", "2:12:45": "O colono e o trabalhador contratado não podem comer dela.", "2:12:46": "O cordeiro deve ser comido numa única casa. Não leve nada da carne para fora da casa, nem quebrem nenhum dos ossos.", "2:12:47": "Toda a assembleia de Israel deve celebrar a Páscoa.", "2:12:48": "Se um estrangeiro que mora entre vocês quiser celebrar a Páscoa para Jeová, todos os do sexo masculino da casa dele deverão ser circuncidados. Só então ele poderá se aproximar para participar da celebração, e ele se tornará como um israelita de nascimento. Mas nenhum incircunciso pode comer dela.", "2:12:49": "A mesma lei será aplicada tanto ao israelita como ao estrangeiro que mora entre vocês.”", "2:12:50": "Portanto, todos os israelitas fizeram assim como Jeová havia ordenado a Moisés e a Arão. Fizeram exatamente assim.", "2:12:51": "Naquele mesmo dia, Jeová tirou os israelitas e as suas multidões da terra do Egito.", "2:14:1": "Jeová disse então a Moisés:", "2:14:2": "“Diga aos israelitas que voltem e acampem diante de Pi-Hairote, entre Migdol e o mar, à vista de Baal-Zefom. Vocês devem acampar junto ao mar, em frente a Baal-Zefom.", "2:14:3": "Então Faraó dirá sobre os israelitas: ‘Eles estão vagueando confusos pelo país. O deserto os encurralou.’", "2:14:4": "Deixarei o coração de Faraó ficar endurecido. Ele os perseguirá, e eu me glorificarei por meio de Faraó e todo o seu exército; e os egípcios certamente saberão que eu sou Jeová.” E os israelitas fizeram assim.", "2:14:5": "Mais tarde, comunicou-se ao rei do Egito que o povo tinha fugido. Imediatamente, Faraó e os seus servos mudaram de ideia a respeito do povo e disseram: “Por que fizemos isso? Libertamos os israelitas, nossos escravos!”", "2:14:6": "De modo que ele aprontou seus carros de guerra e levou seus homens consigo.", "2:14:7": "Pegou os 600 melhores carros de guerra e todos os outros carros do Egito, com guerreiros em cada um deles.", "2:14:8": "Assim Jeová deixou o coração de Faraó, rei do Egito, ficar endurecido, e este foi atrás dos israelitas, enquanto os israelitas saíam confiantes.", "2:14:9": "Os egípcios os perseguiram, e todos os cavalos dos carros de guerra de Faraó, os seus cavaleiros e o seu exército se aproximaram dos israelitas enquanto estes estavam acampados à beira do mar, junto a Pi-Hairote, em frente a Baal-Zefom.", "2:14:10": "Quando Faraó chegou mais perto, os israelitas levantaram os olhos e viram que os egípcios vinham atrás deles. Os israelitas ficaram apavorados e começaram a clamar a Jeová.", "2:14:11": "Eles disseram a Moisés: “É porque não há sepulturas no Egito que você nos trouxe para cá, para morrermos no deserto? O que foi que você nos fez, tirando-nos do Egito?", "2:14:12": "Não lhe dissemos no Egito: ‘Deixe-nos em paz, para servirmos os egípcios’? Pois é melhor servirmos os egípcios do que morrermos no deserto.”", "2:14:13": "Então Moisés disse ao povo: “Não tenham medo. Mantenham-se firmes e vejam a salvação da parte de Jeová, que ele realizará hoje para vocês. Pois os egípcios que estão vendo hoje, vocês nunca mais verão.", "2:14:14": "O próprio Jeová lutará por vocês, e vocês ficarão em silêncio.”", "2:14:15": "E Jeová disse a Moisés: “Por que você persiste em clamar a mim? Diga aos israelitas que levantem acampamento.", "2:14:16": "Quanto a você, erga o seu bastão, estenda a mão sobre o mar e divida-o, para que os israelitas possam passar pelo meio do mar em terra seca.", "2:14:17": "E eu deixarei o coração dos egípcios ficar endurecido, de modo que eles entrarão no mar atrás dos israelitas. Assim eu me glorificarei por meio de Faraó e todo o seu exército, seus carros de guerra e seus cavaleiros.", "2:14:18": "E os egípcios certamente saberão que eu sou Jeová, quando eu me glorificar por meio de Faraó, seus carros de guerra e seus cavaleiros.”", "2:14:19": "Então o anjo do verdadeiro Deus, que ia à frente do povo de Israel, se afastou e foi para a retaguarda, e a coluna de nuvem que estava na frente deles se moveu para a retaguarda e ficou atrás deles.", "2:14:20": "Assim ela ficou entre o exército dos egípcios e o povo de Israel. De um lado, a nuvem causava escuridão; do outro lado, iluminava a noite. Desse modo um grupo não chegou perto do outro grupo durante toda a noite.", "2:14:21": "Então Moisés estendeu a mão sobre o mar, e Jeová fez o mar recuar por meio de um forte vento leste, durante toda a noite, transformando o leito do mar em terra seca, e as águas foram divididas.", "2:14:22": "Assim os israelitas passaram pelo meio do mar em terra seca, enquanto as águas formavam uma muralha à sua direita e à sua esquerda.", "2:14:23": "Os egípcios os perseguiram, e todos os cavalos de Faraó, seus carros de guerra e seus cavaleiros começaram a ir atrás deles para dentro do mar.", "2:14:24": "Durante a madrugada, Jeová olhou da coluna de fogo e nuvem para o exército dos egípcios, e pôs o exército dos egípcios em confusão.", "2:14:25": "Ele desprendeu as rodas dos seus carros, de modo que os dirigiam com dificuldade. Então os egípcios disseram: “Vamos fugir dos israelitas, porque Jeová está lutando por eles contra os egípcios.”", "2:14:26": "Então Jeová disse a Moisés: “Estenda a mão sobre o mar, para que as águas voltem sobre os egípcios, sobre seus carros de guerra e seus cavaleiros.”", "2:14:27": "Moisés estendeu imediatamente a mão sobre o mar e, ao amanhecer, o mar voltou ao estado normal. Os egípcios tentaram escapar das águas, mas Jeová lançou os egípcios no meio do mar.", "2:14:28": "As águas voltaram e cobriram os carros de guerra e os cavaleiros de todo o exército de Faraó, que haviam entrado no mar atrás dos israelitas. Não se deixou sobrar nem sequer um deles.", "2:14:29": "Mas os israelitas andaram em terra seca no leito do mar, e as águas formaram uma muralha à sua direita e à sua esquerda.", "2:14:30": "Assim, naquele dia, Jeová salvou Israel das mãos dos egípcios, e Israel viu os egípcios mortos à beira do mar.", "2:14:31": "Israel viu também o grande poder que Jeová usou contra os egípcios, e o povo começou a temer a Jeová e a ter fé em Jeová e em seu servo Moisés.", "9:15:1": "Samuel disse então a Saul: “Jeová me enviou para ungi-lo rei sobre o povo dele, Israel. Agora escute o que Jeová tem a dizer.", "9:15:2": "Assim diz Jeová dos exércitos: ‘Ajustarei contas com os amalequitas pelo que fizeram a Israel quando se opuseram aos israelitas no caminho, quando estes saíam do Egito.", "9:15:3": "Agora vá, golpeie os amalequitas e entregue-os à destruição, junto com tudo o que eles têm. Não os poupe; mate homens e mulheres, crianças e bebês, bois e ovelhas, camelos e jumentos.’”", "9:15:4": "Saul convocou o exército e o contou em Telaim: havia 200.000 soldados e 10.000 homens de Judá.", "9:15:5": "Saul avançou até a cidade de Amaleque e armou uma emboscada junto ao vale.", "9:15:6": "Saul disse então aos queneus: “Retirem-se, saiam do meio dos amalequitas, para que eu não destrua vocês junto com eles. Pois vocês demonstraram amor leal para com todo o povo de Israel quando eles saíram do Egito.” Portanto, os queneus se retiraram do meio de Amaleque.", "9:15:7": "Depois disso, Saul golpeou os amalequitas desde Havilá até Sur, que fica junto ao Egito.", "9:15:8": "Ele capturou vivo Agague, rei de Amaleque, mas o restante do povo ele entregou à destruição com a espada.", "9:15:9": "No entanto, Saul e o povo pouparam Agague e o melhor das ovelhas e dos bois, os mais gordos, e também os carneiros e tudo o que era bom. Eles não quiseram entregá-los à destruição. Mas todos os bens que eram inúteis e indesejáveis eles entregaram à destruição.", "9:15:10": "Então Samuel recebeu a seguinte palavra de Jeová:", "9:15:11": "“Lamento ter feito Saul rei, pois ele deixou de me seguir e não cumpriu as minhas palavras.” Samuel ficou muito aflito, e clamou a Jeová a noite inteira.", "9:15:12": "Quando Samuel se levantou de manhã cedo para se encontrar com Saul, foi informado: “Saul foi a Carmelo e construiu ali um monumento em sua própria honra. Depois partiu e voltou a Gilgal.”", "9:15:13": "Quando Samuel finalmente se encontrou com ele, Saul lhe disse: “Que Jeová o abençoe. Eu cumpri a ordem de Jeová.”", "9:15:14": "Mas Samuel disse: “Então por que estou ouvindo o barulho de ovelhas e de bois?”", "9:15:15": "Saul respondeu: “Foram tomados dos amalequitas, pois o povo poupou o melhor das ovelhas e dos bois para sacrificá-los a Jeová, seu Deus; mas o que sobrou entregamos à destruição.”", "9:15:16": "Então Samuel disse a Saul: “Já chega! Vou lhe dizer o que Jeová me falou na noite passada.” E ele disse: “Fale!”", "9:15:17": "Samuel continuou: “Você não se achava insignificante quando se tornou cabeça das tribos de Israel e quando Jeová o ungiu rei sobre Israel?", "9:15:18": "Mais tarde Jeová o enviou numa missão e disse: ‘Vá, entregue à destruição esses amalequitas pecadores. Lute contra eles até exterminá-los.’", "9:15:19": "Então por que você não obedeceu à voz de Jeová? Em vez de obedecer, você avançou gananciosamente sobre o despojo e fez o que era mau aos olhos de Jeová!”", "9:15:20": "No entanto, Saul disse a Samuel: “Mas eu obedeci à voz de Jeová! Fui na missão em que Jeová me enviou, trouxe Agague, rei de Amaleque, e entreguei os amalequitas à destruição.", "9:15:21": "Mas os homens pegaram do despojo ovelhas e bois, o melhor do que tinha sido condenado à destruição, para sacrificar a Jeová, seu Deus, em Gilgal.”", "9:15:22": "Samuel disse então: “Será que Jeová tem tanto prazer em ofertas queimadas e sacrifícios como em que se obedeça à voz de Jeová? Pois saiba que obedecer é melhor do que um sacrifício, e prestar atenção é melhor do que a gordura de carneiros;", "9:15:23": "porque a rebeldia é igual ao pecado da adivinhação, e a presunção é igual ao uso de poder mágico e idolatria. Visto que você rejeitou a palavra de Jeová, ele rejeitou você como rei.”", "9:15:24": "Saul disse então a Samuel: “Pequei, pois desobedeci à ordem de Jeová e às instruções que o senhor me deu, porque fiquei com medo do povo e fiz o que eles queriam.", "9:15:25": "E agora, por favor, perdoe o meu pecado e volte comigo, para que eu me curve diante de Jeová.”", "9:15:26": "Mas Samuel disse a Saul: “Não voltarei com você, pois você rejeitou a palavra de Jeová, e Jeová o rejeitou como rei de Israel.”", "9:15:27": "Quando Samuel se virou para ir embora, Saul agarrou a barra da sua túnica sem mangas, mas ela rasgou.", "9:15:28": "Então Samuel lhe disse: “Jeová arrancou hoje de você o reino de Israel, e ele o dará ao seu próximo, que é melhor do que você.", "9:15:29": "Além disso, o Glorioso de Israel não deixará de cumprir a sua palavra nem mudará de ideia, pois Ele não é um homem para mudar de ideia.”", "9:15:30": "Então ele disse: “Pequei. Mas, por favor, honre-me diante dos anciãos do meu povo e diante de Israel. Volte comigo, e eu me curvarei diante de Jeová, seu Deus.”", "9:15:31": "Portanto, Samuel voltou com Saul, e Saul se curvou diante de Jeová.", "9:15:32": "E Samuel disse: “Tragam-me Agague, rei de Amaleque.” Então Agague chegou até ele com relutância, pois tinha dito a si mesmo: ‘Com certeza o risco de morte já passou.’", "9:15:33": "No entanto, Samuel disse: “Assim como a sua espada deixou muitas mulheres sem filhos, sua mãe também ficará sem filhos.” Em seguida Samuel cortou Agague em pedaços perante Jeová em Gilgal.", "9:15:34": "Depois Samuel foi para Ramá, e Saul foi para a sua casa em Gibeá de Saul.", "9:15:35": "Samuel não viu mais Saul até o dia da sua morte, pois Samuel ficou muito triste por causa de Saul. E Jeová lamentou ter feito Saul rei de Israel.", "11:3:1": "Salomão aliou-se por casamento a Faraó, rei do Egito. Ele se casou com a filha de Faraó. Ele a levou para a Cidade de Davi até que terminasse a construção da sua própria casa e da casa de Jeová, bem como da muralha em volta de Jerusalém.", "11:3:2": "Mas o povo ainda oferecia sacrifícios nos altos sagrados, porque até aquela época ainda não se tinha construído uma casa para o nome de Jeová.", "11:3:3": "Salomão continuava a amar a Jeová, andando nos decretos de Davi, seu pai, só que oferecia sacrifícios e fazia fumegar ofertas nos altos sagrados.", "11:3:4": "O rei foi a Gibeão para oferecer sacrifícios, pois aquele era o alto sagrado mais destacado. Salomão ofereceu mil sacrifícios queimados naquele altar.", "11:3:5": "Em Gibeão, Jeová apareceu de noite a Salomão num sonho. Deus lhe disse: “Peça o que você gostaria que eu lhe desse.”", "11:3:6": "Então Salomão disse: “Tu demonstraste grande amor leal ao teu servo Davi, meu pai, pois ele andou diante de ti de modo fiel e justo, e com um coração reto. E tu continuas a demonstrar-lhe este grande amor leal até hoje, dando-lhe um filho para sentar-se no seu trono.", "11:3:7": "E agora, Jeová, meu Deus, tu fizeste teu servo rei no lugar de Davi, meu pai, embora eu seja apenas um jovem inexperiente.", "11:3:8": "Teu servo está entre o povo que escolheste, um povo tão grande que não pode ser contado nem enumerado.", "11:3:9": "Portanto, concede ao teu servo um coração obediente para julgar o teu povo, para discernir o bem do mal, pois quem pode julgar este teu povo, que é tão numeroso?”", "11:3:10": "O pedido que Salomão fez agradou a Jeová.", "11:3:11": "Então Deus lhe disse: “Visto que você pediu isso, e não pediu uma vida longa, nem riquezas, nem a morte dos seus inimigos, mas pediu entendimento para ouvir questões judiciais,", "11:3:12": "farei o que você pediu. Eu lhe darei um coração sábio e entendido, de modo que nunca houve nem haverá ninguém igual a você.", "11:3:13": "Além disso, vou dar-lhe também o que não pediu, tanto riquezas como glória, de modo que não haverá nenhum outro rei igual a você durante a sua vida.", "11:3:14": "E, se você andar nos meus caminhos, guardando os meus decretos e os meus mandamentos, assim como fez Davi, seu pai, também vou dar-lhe uma vida longa.”", "11:3:15": "Quando Salomão acordou, percebeu que tinha sido um sonho. Ele voltou então para Jerusalém, ficou de pé diante da Arca do Pacto de Jeová e ofereceu sacrifícios queimados e ofertas de participação em comum. Fez também um banquete para todos os seus servos.", "11:3:16": "Naqueles dias, duas prostitutas foram ao rei e ficaram de pé diante dele.", "11:3:17": "Uma das mulheres disse: “Por favor, meu senhor, eu e esta mulher moramos na mesma casa, e eu dei à luz quando ela estava na casa.", "11:3:18": "Três dias depois de eu ter dado à luz, esta mulher também deu à luz. Estávamos juntas, só nós duas; não havia ninguém conosco na casa.", "11:3:19": "Durante a noite, o filho desta mulher morreu, porque ela se deitou sobre ele.", "11:3:20": "Então ela se levantou no meio da noite, enquanto eu, a escrava do meu senhor, dormia, e tirou o meu filho do meu lado e o colocou ao lado dela; e o filho dela, que estava morto, ela colocou nos meus braços.", "11:3:21": "Quando me levantei de manhã para amamentar o meu filho, percebi que ele estava morto. Assim, olhei bem para ele e vi que não era o filho que eu tinha dado à luz.”", "11:3:22": "Mas a outra mulher disse: “Não! O meu filho é o vivo, e o seu filho é o morto!” E a primeira mulher dizia: “Não! O seu filho é o morto, e o meu filho é o vivo!” E assim discutiam perante o rei.", "11:3:23": "Por fim, o rei disse: “Uma diz: ‘O meu filho é o que está vivo, e o seu filho é o que está morto!’ e a outra diz: ‘Não! O seu filho é o morto, e o meu filho é o vivo!’”", "11:3:24": "Então o rei disse: “Tragam uma espada.” Assim, trouxeram uma espada para o rei.", "11:3:25": "E o rei disse: “Cortem o menino vivo em dois, e deem metade a uma mulher e metade à outra.”", "11:3:26": "Imediatamente a mulher cujo filho era o vivo, movida pela compaixão por seu filho, implorou ao rei: “Por favor, meu senhor! Deem o menino vivo a ela! Não o matem!” Mas a outra mulher dizia: “Ele não será nem meu nem seu! Podem cortá-lo em dois!”", "11:3:27": "Então o rei disse: “Deem o menino vivo à primeira mulher, não o matem! Ela é a mãe.”", "11:3:28": "E todo o Israel soube da decisão judicial que o rei havia proferido, e ficaram impressionados com o rei, pois viram que a sabedoria de Deus estava com ele para executar a justiça.", "14:6:1": "Então Salomão disse: “Jeová disse que residiria em densas nuvens.", "14:6:2": "Agora eu construí para ti uma magnífica morada, um lugar estabelecido para nele residires para sempre.”", "14:6:3": "Então o rei se virou para toda a congregação de Israel e começou a abençoá-la, enquanto toda a congregação de Israel estava de pé.", "14:6:4": "E ele disse: “Que Jeová, o Deus de Israel, seja louvado, aquele que cumpriu com a própria mão o que a sua boca havia prometido a Davi, meu pai:", "14:6:5": "‘Desde o dia em que tirei o meu povo da terra do Egito, não escolhi nenhuma cidade dentre todas as tribos de Israel a fim de nela construir uma casa para que o meu nome permanecesse ali, e não escolhi nenhum homem para que se tornasse líder do meu povo Israel.", "14:6:6": "Mas escolhi Jerusalém para que o meu nome permanecesse ali e escolhi Davi para reinar sobre o meu povo Israel.’", "14:6:7": "E o desejo de coração de Davi, meu pai, era construir uma casa para o nome de Jeová, o Deus de Israel.", "14:6:8": "Mas Jeová disse a Davi, meu pai: ‘O seu desejo de coração é construir uma casa para o meu nome, e é bom que você tenha esse desejo no coração.", "14:6:9": "Mas você não construirá a casa; o seu filho, que procederá de você, é quem construirá a casa para o meu nome.’", "14:6:10": "Jeová cumpriu a promessa que fez, pois sucedi a Davi, meu pai, e me sentei no trono de Israel, assim como Jeová prometeu. Também construí a casa para o nome de Jeová, o Deus de Israel,", "14:6:11": "e coloquei ali a Arca, que contém o pacto que Jeová fez com o povo de Israel.”", "14:6:12": "Então ele ficou de pé diante do altar de Jeová, perante toda a congregação de Israel, e estendeu as mãos.", "14:6:13": "(Salomão tinha feito uma plataforma de cobre e a tinha colocado no meio do pátio. Ela tinha cinco côvados de comprimento, cinco côvados de largura e três côvados de altura; e ele ficou de pé sobre ela.) E ele se ajoelhou perante toda a congregação de Israel, estendeu as mãos para os céus", "14:6:14": "e disse: “Ó Jeová, Deus de Israel, não há Deus igual a ti nos céus nem na terra; tu guardas o pacto e demonstras amor leal aos teus servos que andam diante de ti de todo o coração.", "14:6:15": "Tu cumpriste a promessa que fizeste ao teu servo Davi, meu pai. Fizeste a promessa com a tua própria boca, e hoje a cumpriste com a tua própria mão.", "14:6:16": "E agora, ó Jeová, Deus de Israel, cumpre a promessa que fizeste ao teu servo Davi, meu pai, quando disseste: ‘Sempre haverá um descendente seu diante de mim para sentar no trono de Israel, desde que os seus filhos prestem atenção ao caminho deles, andando na minha lei assim como você andou diante de mim.’", "14:6:17": "E agora, ó Jeová, Deus de Israel, que se cumpra a promessa que fizeste ao teu servo Davi.", "14:6:18": "“Mas será que Deus realmente morará com a humanidade na terra? Os céus, sim, o céu dos céus, não te podem conter; quanto menos, então, esta casa que construí!", "14:6:19": "Agora, presta atenção à oração e ao pedido de favor do teu servo, ó Jeová, meu Deus, e escuta o clamor por ajuda e a oração que o teu servo faz diante de ti.", "14:6:20": "Que os teus olhos vigiem dia e noite esta casa, o lugar onde disseste que porias o teu nome, e que escutes a oração que o teu servo faz em direção a este lugar.", "14:6:21": "Escuta as súplicas por ajuda do teu servo e as súplicas do teu povo Israel quando orarem em direção a este lugar. Que tu ouças do lugar da tua morada, os céus; sim, que tu ouças e perdoes.", "14:6:22": "“Se um homem pecar contra o seu próximo e for obrigado a fazer um juramento, ficando assim sujeito aos termos desse juramento, e ele for até o teu altar nesta casa enquanto estiver sob esse juramento,", "14:6:23": "que tu ouças desde os céus, e que ajas e julgues os teus servos: que retribuas àquele que fez o mal, fazendo os seus atos recair sobre a sua própria cabeça, e que declares inocente àquele que é justo, recompensando-o conforme a sua própria justiça.", "14:6:24": "“E, se o teu povo Israel for derrotado por um inimigo, por terem persistido em pecar contra ti, e eles voltarem e glorificarem o teu nome, e orarem e implorarem o teu favor perante ti nesta casa,", "14:6:25": "então que tu ouças desde os céus, e que perdoes o pecado do teu povo Israel e os tragas de volta à terra que deste a eles e aos seus antepassados.", "14:6:26": "“Se os céus se fecharem e não chover, por teu povo ter persistido em pecar contra ti, e eles orarem em direção a este lugar e glorificarem o teu nome, e recuarem do seu pecado, por tu lhes teres ensinado a ser humildes,", "14:6:27": "então que tu ouças desde os céus e perdoes o pecado dos teus servos, do teu povo Israel, e os instruas sobre o bom caminho em que devem andar; e que tu tragas chuva sobre a terra que deste ao teu povo como herança.", "14:6:28": "“Se houver uma fome no país, ou peste, calor abrasador, bolor, nuvens de gafanhotos, ou gafanhotos devastadores; ou se os inimigos os cercarem em alguma das cidades do país, ou se qualquer outro tipo de praga ou doença ocorrer,", "14:6:29": "e um homem ou todo o teu povo Israel fizer uma oração ou apresentar um pedido de favor, qualquer que seja (pois cada um conhece a sua própria aflição e a sua própria dor), quando eles estenderem as mãos em direção a esta casa,", "14:6:30": "então que tu ouças desde os céus, teu lugar de morada, que perdoes, e que recompenses a cada um conforme todos os seus caminhos, pois conheces o seu coração (só tu realmente conheces o coração do homem),", "14:6:31": "para que te temam, andando nos teus caminhos todos os dias em que viverem na terra que deste aos nossos antepassados.", "14:6:32": "“Quanto ao estrangeiro que não faz parte do teu povo Israel e que vier de uma terra distante por causa do teu grande nome, da tua mão poderosa e do teu braço estendido, e que vier e orar em direção a esta casa,", "14:6:33": "que tu também o ouças desde os céus, teu lugar de morada, e que faças tudo que o estrangeiro te pedir, para que todos os povos da terra conheçam o teu nome e te temam assim como o teu povo Israel faz, e para que saibam que o teu nome é invocado sobre esta casa que construí.", "14:6:34": "“Se o teu povo for à guerra contra os inimigos, seguindo o caminho pelo qual os enviares, e eles orarem a ti em direção a esta cidade que escolheste e em direção à casa que construí para o teu nome,", "14:6:35": "então que tu ouças desde os céus a sua oração e o seu pedido de favor, e lhes faças justiça.", "14:6:36": "“Se eles pecarem contra ti (pois não há homem que não peque), e ficares furioso com eles e os entregares a um inimigo que os leve cativos para uma terra distante ou próxima,", "14:6:37": "e eles caírem em si na terra para onde forem levados cativos, e voltarem para ti, e implorarem o teu favor na terra em que estiverem cativos, dizendo: ‘Pecamos, fizemos o que é errado e o que é mau’,", "14:6:38": "e eles voltarem para ti de todo o coração e de toda a alma na terra do cativeiro, para onde foram levados cativos, e orarem em direção à terra que deste aos seus antepassados, à cidade que escolheste e à casa que construí para o teu nome,", "14:6:39": "então que tu ouças a sua oração e o seu pedido de favor desde os céus, teu lugar de morada, e lhes faças justiça, e perdoes o teu povo que pecou contra ti.", "14:6:40": "“Agora, ó meu Deus, por favor, que os teus olhos estejam abertos e que os teus ouvidos estejam atentos à oração feita neste lugar.", "14:6:41": "E agora, ó Jeová Deus, sobe ao teu lugar de descanso, tu e a Arca do teu poder. Que os teus sacerdotes, ó Jeová Deus, estejam vestidos de salvação, e que os que são leais a ti se alegrem por causa da tua bondade.", "14:6:42": "Ó Jeová Deus, não rejeites o teu ungido. Lembra-te do teu amor leal a Davi, teu servo.”", "14:19:1": "E Jeosafá, rei de Judá, voltou são e salvo para a sua casa em Jerusalém.", "14:19:2": "Jeú, filho de Hanani, o vidente, saiu ao encontro do rei Jeosafá e lhe disse: “É aos maus que o senhor deve ajudar, e é aos que odeiam a Jeová que deve amar? Por causa disso, Jeová está indignado com o senhor.", "14:19:3": "No entanto, há coisas boas no senhor, porque o senhor eliminou do país os postes sagrados e preparou seu coração para buscar o verdadeiro Deus.”", "14:19:4": "Jeosafá continuou morando em Jerusalém, e saiu novamente para visitar o povo, desde Berseba até a região montanhosa de Efraim, a fim de trazê-los de volta para Jeová, o Deus dos seus antepassados.", "14:19:5": "Ele também designou juízes em todo o país, em cada uma de todas as cidades fortificadas de Judá.", "14:19:6": "E disse aos juízes: “Prestem atenção ao que fazem, pois vocês não julgam para o homem, mas para Jeová; e ele está com vocês quando julgam.", "14:19:7": "Agora, tenham temor de Jeová. Tomem cuidado com o que fazem, pois com Jeová, nosso Deus, não há injustiça, nem parcialidade, nem suborno.”", "14:19:8": "Jeosafá também designou em Jerusalém alguns levitas e sacerdotes, e alguns cabeças das casas paternas de Israel, para servir como juízes para Jeová e para decidir as causas dos habitantes de Jerusalém.", "14:19:9": "E lhes ordenou: “Isto é o que vocês devem fazer, com temor de Jeová, com fidelidade e de pleno coração:", "14:19:10": "sempre que os seus irmãos que moram em outras cidades trouxerem uma causa que envolva derramamento de sangue ou uma questão sobre uma lei, um mandamento, decretos ou decisões judiciais, vocês devem aconselhá-los para que eles não se tornem culpados perante Jeová; do contrário, ele ficará indignado com vocês e seus irmãos. Isso é o que vocês devem fazer para não se tornarem culpados.", "14:19:11": "Aqui está Amarias, o principal sacerdote, que será o encarregado de vocês em todo assunto relacionado ao serviço de Jeová. Zebadias, filho de Ismael, será o líder da casa de Judá em todo assunto relacionado ao rei. E os levitas servirão como oficiais para vocês. Sejam fortes e ajam, e que Jeová esteja com os que fizerem o que é bom.”", "14:20:1": "Mais tarde, os moabitas e os amonitas, junto com alguns dos amonins, vieram guerrear contra Jeosafá.", "14:20:2": "Então informaram a Jeosafá: “Uma grande multidão veio contra o senhor da região do mar, de Edom, e eles já estão em Hazazom-Tamar, isto é, En-Gedi.”", "14:20:3": "Em vista disso, Jeosafá ficou com medo e decidiu recorrer a Jeová. Assim, proclamou um jejum para todo o Judá.", "14:20:4": "E o povo de Judá se reuniu para consultar a Jeová; vieram de todas as cidades de Judá para consultar a Jeová.", "14:20:5": "Jeosafá ficou então de pé na congregação de Judá e Jerusalém, na casa de Jeová, diante do pátio novo,", "14:20:6": "e disse: “Ó Jeová, Deus dos nossos antepassados, não és tu Deus nos céus, e não dominas sobre todos os reinos das nações? Na tua mão há força e poder, e ninguém pode se manter firme contra ti.", "14:20:7": "Ó nosso Deus, não expulsaste os habitantes desta terra de diante do teu povo Israel, e não a deste como propriedade permanente à descendência do teu amigo Abraão?", "14:20:8": "Eles se estabeleceram nela e construíram ali um santuário para o teu nome, dizendo:", "14:20:9": "‘Se vier sobre nós calamidade — espada, julgamento desfavorável, peste ou fome —, que fiquemos de pé diante desta casa e diante de ti (pois o teu nome está nesta casa) e clamemos a ti por ajuda na nossa aflição, e que tu ouças e nos salves.’", "14:20:10": "Aqui estão os homens de Amom, de Moabe e da região montanhosa de Seir, cujas terras tu não deixaste Israel invadir quando saiu da terra do Egito. Israel se desviou deles e não os destruiu.", "14:20:11": "Agora eles nos recompensam vindo nos expulsar da tua propriedade, que nos deste como herança.", "14:20:12": "Ó nosso Deus, não executarás o julgamento neles? Pois não podemos fazer nada diante dessa grande multidão que vem contra nós. Não sabemos o que devemos fazer, mas os nossos olhos se fixam em ti.”", "14:20:13": "Enquanto isso, todos os homens de Judá estavam diante de Jeová, junto com suas esposas e seus filhos, incluindo as crianças.", "14:20:14": "Então, no meio da congregação, o espírito de Jeová veio sobre Jaaziel, filho de Zacarias, filho de Benaia, filho de Jeiel, filho de Matanias, levita dos filhos de Asafe.", "14:20:15": "Ele disse: “Prestem atenção, todo o Judá, habitantes de Jerusalém e rei Jeosafá! Assim lhes diz Jeová: ‘Não tenham medo nem fiquem apavorados por causa dessa grande multidão, pois a batalha não é sua, mas de Deus.", "14:20:16": "Amanhã desçam contra eles. Eles estarão subindo pelo desfiladeiro de Ziz, e vocês os encontrarão no fim do vale, em frente ao deserto de Jeruel.", "14:20:17": "Vocês não terão de lutar nesta batalha. Tomem a sua posição, fiquem parados e vejam a salvação de Jeová a seu favor. Ó Judá e Jerusalém, não tenham medo nem fiquem apavorados. Amanhã saiam ao encontro deles, e Jeová estará com vocês.’”", "14:20:18": "Imediatamente Jeosafá se curvou com o rosto por terra, e todo o Judá e os habitantes de Jerusalém se prostraram diante de Jeová para adorar a Jeová.", "14:20:19": "Então os levitas que eram descendentes dos coatitas e dos coraítas se levantaram para louvar a Jeová, o Deus de Israel, com voz bem alta.", "14:20:20": "Na manhã seguinte, levantaram-se cedo e partiram para o deserto de Tecoa. Quando estavam partindo, Jeosafá ficou de pé e disse: “Ouçam-me, ó Judá e habitantes de Jerusalém! Tenham fé em Jeová, seu Deus, para que possam permanecer firmes. Tenham fé nos Seus profetas e vocês serão bem-sucedidos.”", "14:20:21": "Depois de consultar o povo, ele designou homens para cantarem a Jeová e lhe darem louvor com vestes santas, indo à frente dos homens armados, dizendo: “Agradeçam a Jeová, pois o seu amor leal dura para sempre.”", "14:20:22": "Quando começaram a cantar louvores com alegria, Jeová armou uma emboscada contra os homens de Amom, de Moabe e da região montanhosa de Seir, que estavam invadindo Judá, e eles mataram uns aos outros.", "14:20:23": "Os amonitas e os moabitas se voltaram contra os habitantes da região montanhosa de Seir para destruí-los e exterminá-los; e, quando acabaram com os habitantes de Seir, destruíram uns aos outros.", "14:20:24": "Quando Judá chegou à torre de vigia do deserto e eles olharam para a multidão, lá estavam os seus cadáveres caídos no chão; não havia sobreviventes.", "14:20:25": "Então Jeosafá e seu povo foram pegar o despojo. Acharam entre eles muitos bens, roupas e objetos preciosos que pegaram dos cadáveres até não poderem carregar mais. Demorou três dias para levarem o despojo, pois havia muita coisa.", "14:20:26": "No quarto dia reuniram-se no vale de Beraca, e ali louvaram a Jeová. É por isso que chamaram aquele lugar de vale de Beraca, como é conhecido até hoje.", "14:20:27": "Então todos os homens de Judá e de Jerusalém, com Jeosafá à sua frente, voltaram a Jerusalém com alegria, pois Jeová tinha feito com que eles se alegrassem com a vitória sobre os seus inimigos.", "14:20:28": "Chegaram assim a Jerusalém com instrumentos de cordas, harpas e trombetas, e foram à casa de Jeová.", "14:20:29": "E todos os reinos das terras ficaram com medo de Deus quando souberam que Jeová tinha lutado contra os inimigos de Israel.", "14:20:30": "Assim o reino de Jeosafá teve paz, e seu Deus continuou a dar-lhe descanso de todos os inimigos ao seu redor.", "14:20:31": "E Jeosafá continuou reinando sobre Judá. Ele tinha 35 anos de idade quando se tornou rei, e reinou por 25 anos em Jerusalém. O nome da sua mãe era Azuba, filha de Sili.", "14:20:32": "Ele andava no caminho de Asa, seu pai. Não se desviou dele, e fez o que era certo aos olhos de Jeová.", "14:20:33": "Mas os altos sagrados não foram removidos, e o povo ainda não tinha preparado seu coração para buscar o Deus dos seus antepassados.", "14:20:34": "Os outros acontecimentos da história de Jeosafá, do começo ao fim, estão registrados nos escritos de Jeú, filho de Hanani, que foram incluídos no Livro dos Reis de Israel.", "14:20:35": "Depois Jeosafá, rei de Judá, fez uma aliança com Acazias, rei de Israel, que fazia o que era mau.", "14:20:36": "Assim, eles se tornaram sócios na construção de navios que iriam a Társis, e construíram os navios em Eziom-Geber.", "14:20:37": "No entanto, Eliézer, filho de Dodavaú, de Maressa, profetizou contra Jeosafá, dizendo: “Visto que o senhor fez uma aliança com Acazias, Jeová destruirá os seus trabalhos.” Assim, os navios naufragaram e não puderam chegar a Társis.", "19:101:1": "Cantarei sobre amor leal e justiça. A ti, ó Jeová, cantarei louvores.", "19:101:2": "Agirei com prudência e de modo irrepreensível. Quando virás me ajudar? Dentro da minha casa, andarei com o coração íntegro.", "19:101:3": "Não porei nada sem valor diante dos meus olhos. Odeio as ações das pessoas que se desviam do que é certo; Não terei nada que ver com elas.", "19:101:4": "Longe de mim está o coração tortuoso; Não aceitarei o que é mau.", "19:101:5": "Aquele que às escondidas calunia seu próximo, Eu silenciarei. Aquele que tem olhos arrogantes e coração orgulhoso, Eu não vou tolerar.", "19:101:6": "Olharei para os fiéis da terra, Para que residam comigo. Aquele que anda de modo irrepreensível servirá a mim.", "19:101:7": "Nenhuma pessoa falsa morará na minha casa, E nenhum mentiroso ficará na minha presença.", "19:101:8": "A cada manhã silenciarei todos os maus da terra, Eliminarei da cidade de Jeová todos os malfeitores.", "19:106:1": "Louvem a Jah! Agradeçam a Jeová, pois ele é bom; Seu amor leal dura para sempre.", "19:106:2": "Quem pode declarar todas as poderosas realizações de Jeová Ou proclamar todos os seus atos louváveis?", "19:106:3": "Felizes são os que agem com justiça, Que sempre fazem o que é certo.", "19:106:4": "Lembra-te de mim, ó Jeová, quando mostrares favor ao teu povo. Cuida de mim com os teus atos de salvação,", "19:106:5": "Para que eu experimente a bondade que demonstras aos teus escolhidos, Para que eu me alegre junto com a tua nação, Para que eu te louve com orgulho, junto com a tua herança.", "19:106:6": "Pecamos como os nossos antepassados; Erramos, fizemos o que é mau.", "19:106:7": "Nossos antepassados no Egito não deram valor aos teus atos maravilhosos. Não se lembraram do teu imenso amor leal, Mas se rebelaram junto ao mar, o mar Vermelho.", "19:106:8": "No entanto ele os salvou por causa do Seu nome, Para tornar conhecido o seu poder.", "19:106:9": "Ele censurou o mar Vermelho, e este se secou; Ele os conduziu pelas profundezas do mar como que por um deserto;", "19:106:10": "Ele os salvou das mãos daquele que os odiava, E os resgatou das mãos do inimigo.", "19:106:11": "As águas cobriram os seus adversários; Nem sequer um deles sobreviveu.", "19:106:12": "Então tiveram fé na promessa dele; Começaram a cantar louvores a ele.", "19:106:13": "Mas se esqueceram depressa do que ele havia feito; Não esperaram para saber a orientação dele.", "19:106:14": "Cederam aos seus desejos egoístas no ermo; Puseram Deus à prova no deserto.", "19:106:15": "Ele lhes deu o que pediram, Mas depois os atingiu com uma doença que os consumiu.", "19:106:16": "No acampamento, ficaram com inveja de Moisés E de Arão, o santo de Jeová.", "19:106:17": "Então a terra se abriu e engoliu Datã, E cobriu os que estavam reunidos com Abirão.", "19:106:18": "Um fogo ardeu no meio do grupo deles; Uma chama devorou os maus.", "19:106:19": "Fizeram um bezerro em Horebe E se curvaram diante de uma estátua de metal;", "19:106:20": "Trocaram a minha glória Pela representação de um boi que come capim.", "19:106:21": "Esqueceram-se de Deus, seu Salvador, Aquele que fez grandes coisas no Egito,", "19:106:22": "Atos maravilhosos na terra de Cã, Coisas impressionantes no mar Vermelho.", "19:106:23": "Ele estava prestes a ordenar que fossem aniquilados, Mas Moisés, seu escolhido, intercedeu junto a ele Para aplacar a sua ira destruidora.", "19:106:24": "Depois eles desprezaram a terra desejável; Não tiveram fé na sua promessa.", "19:106:25": "Ficaram resmungando nas suas tendas; Não escutaram a voz de Jeová.", "19:106:26": "Por isso ele ergueu a mão e jurou Que os faria cair no deserto;", "19:106:27": "Ele faria os seus descendentes cair entre as nações E os espalharia pelas terras.", "19:106:28": "Então eles começaram a adorar Baal de Peor E comeram dos sacrifícios oferecidos aos mortos.", "19:106:29": "Eles provocaram a Deus com as suas ações, E um flagelo irrompeu entre eles.", "19:106:30": "Mas, quando Fineias se levantou e interveio, O flagelo cessou.", "19:106:31": "E isso lhe foi creditado como justiça, Por todas as gerações, para sempre.", "19:106:32": "Eles O provocaram junto às águas de Meribá, E, por causa deles, Moisés sofreu;", "19:106:33": "Amarguraram-lhe o espírito, E ele falou precipitadamente com os seus lábios.", "19:106:34": "Não aniquilaram os povos, Como Jeová lhes havia ordenado.", "19:106:35": "Mas eles se misturaram com as nações E adotaram os costumes delas.", "19:106:36": "Serviam a seus ídolos, E estes se tornaram um laço para eles.", "19:106:37": "Sacrificavam seus filhos E suas filhas a demônios.", "19:106:38": "Derramavam sangue inocente, O sangue de seus próprios filhos e filhas, Que sacrificavam aos ídolos de Canaã; E a terra foi profanada com derramamento de sangue.", "19:106:39": "Eles se tornaram impuros por meio dos seus atos; Cometeram prostituição espiritual por meio das suas ações.", "19:106:40": "Então a ira de Jeová se acendeu contra o seu povo, E ele passou a detestar a sua herança.", "19:106:41": "Entregou-os repetidas vezes às nações, Para que aqueles que os odiavam dominassem sobre eles.", "19:106:42": "Seus inimigos os oprimiram, E eles foram submetidos ao seu poder.", "19:106:43": "Muitas vezes ele os livrou, Mas eles se rebelavam e desobedeciam, E eram humilhados por causa do seu erro.", "19:106:44": "Mas ele via a sua aflição E ouvia o seu clamor por ajuda.", "19:106:45": "Por causa deles, ele se lembrava do seu pacto; E sentia dó, movido pelo seu grande amor leal.", "19:106:46": "Fazia com que todos os que os mantinham cativos Tivessem pena deles.", "19:106:47": "Salva-nos, ó Jeová, nosso Deus, E reúne-nos dentre as nações, Para que possamos dar graças ao teu santo nome E ter grande alegria em louvar a ti.", "19:106:48": "Que Jeová, o Deus de Israel, seja louvado Por toda a eternidade; E que todo o povo diga: “Amém!” Louvem a Jah!", "19:119:1": "Felizes são os irrepreensíveis no seu caminho, Os que andam na lei de Jeová.", "19:119:2": "Felizes são os que acatam as Suas advertências E o buscam de todo o coração.", "19:119:3": "Eles não praticam o mal; Andam nos Seus caminhos.", "19:119:4": "Tu ordenaste Que teus mandamentos fossem cuidadosamente cumpridos.", "19:119:5": "Como eu desejo me manter firme Para cumprir os teus decretos!", "19:119:6": "Então eu não me envergonharia Ao considerar todos os teus mandamentos.", "19:119:7": "Eu te louvarei com um coração reto Ao tomar conhecimento dos teus julgamentos justos.", "19:119:8": "Cumprirei os teus decretos. Que tu nunca me abandones completamente.", "19:119:9": "Como um jovem pode manter puro o seu caminho? Por estar vigilante e agir de acordo com a tua palavra.", "19:119:10": "Eu te busco de todo o coração. Não deixes que eu me desvie dos teus mandamentos.", "19:119:11": "Guardo no coração as tuas declarações, A fim de não pecar contra ti.", "19:119:12": "Que sejas louvado, ó Jeová; Ensina-me os teus decretos.", "19:119:13": "Com os meus lábios declaro Todas as decisões judiciais que proferiste.", "19:119:14": "Alegro-me com as tuas advertências, Mais do que com todas as outras coisas valiosas.", "19:119:15": "Vou meditar nas tuas ordens E manter os olhos nos teus caminhos.", "19:119:16": "Gosto muito dos teus preceitos. Não me esquecerei da tua palavra.", "19:119:17": "Age de modo bondoso com o teu servo, Para que eu viva e obedeça à tua palavra.", "19:119:18": "Abre os meus olhos para que eu veja claramente As coisas maravilhosas da tua lei.", "19:119:19": "Sou apenas um estrangeiro nesta terra. Não escondas de mim os teus mandamentos.", "19:119:20": "O anseio pelos teus julgamentos Consome o meu ser, todo o tempo.", "19:119:21": "Tu censuras os presunçosos, Os amaldiçoados que se desviam dos teus mandamentos.", "19:119:22": "Remove de mim a zombaria e o desprezo, Pois tenho acatado as tuas advertências.", "19:119:23": "Mesmo quando príncipes se sentam juntos e falam contra mim, O teu servo medita nos teus decretos.", "19:119:24": "Gosto muito das tuas advertências; Elas são minhas conselheiras.", "19:119:25": "Estou prostrado no pó. Preserva-me vivo, de acordo com a tua palavra.", "19:119:26": "Declarei a ti os meus caminhos, e tu me respondeste; Ensina-me os teus decretos.", "19:119:27": "Faz-me compreender as tuas ordens, Para que eu medite nos teus atos maravilhosos.", "19:119:28": "Não consigo dormir, de tanta tristeza. Fortalece-me, de acordo com a tua palavra.", "19:119:29": "Afasta de mim o caminho da falsidade E mostra-me favor, ensinando-me a tua lei.", "19:119:30": "Escolhi o caminho da fidelidade. Reconheço que os teus julgamentos são corretos.", "19:119:31": "Apego-me às tuas advertências. Ó Jeová, não me deixes decepcionado.", "19:119:32": "Eu me apressarei em seguir o caminho dos teus mandamentos, Porque abres espaço para isso em meu coração.", "19:119:33": "Ensina-me, ó Jeová, o caminho dos teus decretos, E eu o seguirei até o fim.", "19:119:34": "Dá-me entendimento, Para que eu obedeça à tua lei E a guarde de todo o coração.", "19:119:35": "Guia-me no caminho dos teus mandamentos, Pois nele tenho prazer.", "19:119:36": "Inclina meu coração às tuas advertências, E não à cobiça.", "19:119:37": "Desvia os meus olhos do que é sem valor; Preserva-me vivo no teu caminho.", "19:119:38": "Cumpre a promessa que fizeste ao teu servo, Para que sejas temido.", "19:119:39": "Livra-me da vergonha que me apavora, Pois os teus julgamentos são bons.", "19:119:40": "Vê como anseio pelas tuas ordens. Preserva-me vivo, de acordo com a tua justiça.", "19:119:41": "Que eu experimente o teu amor leal, ó Jeová, A tua salvação, em harmonia com a tua promessa;", "19:119:42": "Então darei uma resposta àquele que zomba de mim, Pois tenho confiança na tua palavra.", "19:119:43": "Jamais tires da minha boca a palavra da verdade, Pois tenho esperado no teu julgamento.", "19:119:44": "Vou guardar constantemente a tua lei, Para todo o sempre.", "19:119:45": "E vou andar por um lugar seguro, Pois busco as tuas ordens.", "19:119:46": "Vou falar sobre as tuas advertências diante de reis E não ficarei envergonhado.", "19:119:47": "Gosto muito dos teus mandamentos, Sim, eu os amo.", "19:119:48": "Levantarei as minhas mãos para os teus mandamentos, que tanto amo, E vou meditar nos teus decretos.", "19:119:49": "Lembra-te da tua palavra ao teu servo, Pela qual me dás esperança.", "19:119:50": "Esse é o meu consolo na minha aflição, Pois a tua declaração me preserva vivo.", "19:119:51": "Os presunçosos zombam muito de mim, Mas não me desvio da tua lei.", "19:119:52": "Lembro-me dos teus julgamentos do passado, ó Jeová, E eles me consolam.", "19:119:53": "Sou tomado de furor por causa dos maus, Que abandonam a tua lei.", "19:119:54": "Teus decretos são cânticos para mim, Onde quer que eu more.", "19:119:55": "Durante a noite, lembro-me do teu nome, ó Jeová, A fim de guardar a tua lei.", "19:119:56": "Esse tem sido o meu costume Porque obedeço às tuas ordens.", "19:119:57": "Jeová é a minha porção; Prometi guardar as tuas palavras.", "19:119:58": "Recorro a ti de todo o coração; Mostra-me favor, de acordo com a tua promessa.", "19:119:59": "Tenho examinado os meus caminhos Para fazer meus pés voltar às tuas advertências.", "19:119:60": "Eu me apresso, e não demoro, Em guardar os teus mandamentos.", "19:119:61": "Cercam-me as cordas dos maus, Mas não me esqueço da tua lei.", "19:119:62": "À meia-noite eu me levanto para agradecer-te Pelos teus julgamentos justos.", "19:119:63": "Sou amigo de todos os que te temem E dos que cumprem as tuas ordens.", "19:119:64": "O teu amor leal, ó Jeová, enche a terra; Ensina-me os teus decretos.", "19:119:65": "Trataste bem o teu servo, Ó Jeová, de acordo com a tua palavra.", "19:119:66": "Ensina-me o bom senso e o conhecimento, Pois tenho confiança nos teus mandamentos.", "19:119:67": "Antes de passar por aflições, eu me desviava, Mas agora guardo a tua declaração.", "19:119:68": "Tu és bom e tuas obras são boas. Ensina-me os teus decretos.", "19:119:69": "Os presunçosos me cobrem de calúnias, Mas eu obedeço às tuas ordens de todo o coração.", "19:119:70": "O coração deles é insensível, Mas eu gosto muito da tua lei.", "19:119:71": "É bom que eu tenha passado por aflições, Para aprender os teus decretos.", "19:119:72": "A lei que proclamaste é boa para mim, Mais do que milhares de peças de ouro e de prata.", "19:119:73": "Tuas mãos me fizeram e me formaram. Dá-me entendimento, Para que eu aprenda os teus mandamentos.", "19:119:74": "Os que te temem se alegram ao me ver, Pois a tua palavra é a minha esperança.", "19:119:75": "Sei, ó Jeová, que os teus julgamentos são justos E que me afligiste por causa da tua fidelidade.", "19:119:76": "Por favor, que o teu amor leal me console, Segundo a promessa que fizeste ao teu servo.", "19:119:77": "Mostra-me misericórdia, para que eu continue vivendo, Pois gosto muito da tua lei.", "19:119:78": "Sejam envergonhados os presunçosos, Pois me maltratam sem motivo. Mas eu meditarei nas tuas ordens.", "19:119:79": "Juntem-se novamente a mim os que te temem, Os que conhecem as tuas advertências.", "19:119:80": "Que o meu coração seja irrepreensível ao obedecer aos teus decretos, Para que eu não seja envergonhado.", "19:119:81": "Eu anseio pela tua salvação, Pois a tua palavra é a minha esperança.", "19:119:82": "Meus olhos anseiam pela tua declaração, Ao passo que digo: “Quando me consolarás?”", "19:119:83": "Pois sou como um odre ressecado pela fumaça, Mas não me esqueço dos teus decretos.", "19:119:84": "Quantos dias o teu servo tem de esperar? Quando trarás o julgamento contra os que me perseguem?", "19:119:85": "Os presunçosos, que desafiam a tua lei, Cavam armadilhas para me apanhar.", "19:119:86": "Todos os teus mandamentos são confiáveis. Sou perseguido sem nenhum motivo. Ajuda-me!", "19:119:87": "Quase me eliminaram da terra, Mas eu não abandonei as tuas ordens.", "19:119:88": "Preserva-me vivo por causa do teu amor leal, Para que eu guarde as advertências que proferiste.", "19:119:89": "Para sempre, ó Jeová, A tua palavra permanecerá nos céus.", "19:119:90": "Tua fidelidade existe por todas as gerações. Estabeleceste a terra, de modo que ela continua firme.", "19:119:91": "Segundo as tuas leis, permanecem até hoje, Pois todas as coisas estão a teu serviço.", "19:119:92": "Se eu não gostasse da tua lei, Eu teria morrido na minha aflição.", "19:119:93": "Nunca me esquecerei das tuas ordens, Porque por meio delas me preservaste vivo.", "19:119:94": "Pertenço a ti. Salva-me, Porque tenho buscado as tuas ordens.", "19:119:95": "Os maus estão à espera para me destruir, Mas eu dou plena atenção às tuas advertências.", "19:119:96": "Tenho visto que toda perfeição tem um limite. Mas o teu mandamento não tem limites.", "19:119:97": "Como eu amo a tua lei! Medito nela o dia inteiro.", "19:119:98": "Teu mandamento me torna mais sábio do que os meus inimigos, Porque ele está comigo para sempre.", "19:119:99": "Tenho mais perspicácia do que todos os meus mestres, Porque medito nas tuas advertências.", "19:119:100": "Ajo com mais entendimento do que os idosos, Porque obedeço às tuas ordens.", "19:119:101": "Recuso-me a andar em um caminho mau, Para guardar a tua palavra.", "19:119:102": "Não rejeito as tuas decisões judiciais, Porque tu me instruíste.", "19:119:103": "Como são doces para o meu paladar as tuas declarações, Mais do que mel para a minha boca!", "19:119:104": "Por causa das tuas ordens, ajo com entendimento. É por isso que odeio todo caminho de falsidade.", "19:119:105": "Tua palavra é lâmpada para o meu pé, E luz para o meu caminho.", "19:119:106": "Fiz um juramento e vou cumpri-lo: Obedecerei às tuas justas decisões judiciais.", "19:119:107": "Passei por intensa aflição. Ó Jeová, preserva-me vivo, de acordo com a tua palavra.", "19:119:108": "Por favor, aceita com prazer as minhas ofertas voluntárias de louvor, ó Jeová, E ensina-me os teus julgamentos.", "19:119:109": "Minha vida está em perigo constante, Mas não me esqueço da tua lei.", "19:119:110": "Os maus prepararam uma armadilha para mim, Mas não me desvio das tuas ordens.", "19:119:111": "As tuas advertências são minha propriedade permanente, Pois são a alegria do meu coração.", "19:119:112": "Eu decidi obedecer aos teus decretos Em todas as ocasiões, até o fim.", "19:119:113": "Odeio os que têm um coração dividido, Mas eu amo a tua lei.", "19:119:114": "Tu és meu abrigo e meu escudo, Pois a tua palavra é a minha esperança.", "19:119:115": "Afastem-se de mim, perversos, Para que eu obedeça aos mandamentos do meu Deus.", "19:119:116": "Sustenta-me, como prometeste, Para que eu continue vivendo; Não deixes que a minha esperança se transforme em desapontamento.", "19:119:117": "Sustenta-me, para que eu seja salvo; Então eu sempre me concentrarei em teus decretos.", "19:119:118": "Tu rejeitas a todos os que se desviam dos teus decretos, Pois são falsos e mentirosos.", "19:119:119": "Lanças fora, como escória, todos os malfeitores da terra. É por isso que eu amo as tuas advertências.", "19:119:120": "O medo de ti faz meu corpo tremer; E tenho temor dos teus julgamentos.", "19:119:121": "Tenho feito o que é justo e reto. Não me abandones aos meus opressores!", "19:119:122": "Garante o bem-estar do teu servo; Que os presunçosos não me oprimam.", "19:119:123": "Meus olhos estão exaustos, à espera da tua salvação E do cumprimento da tua promessa justa.", "19:119:124": "Mostra o teu amor leal ao teu servo E ensina-me os teus decretos.", "19:119:125": "Sou teu servo; dá-me entendimento, Para que eu compreenda as tuas advertências.", "19:119:126": "Chegou o tempo de Jeová agir, Pois eles violaram a tua lei.", "19:119:127": "Por isso amo os teus mandamentos Mais do que o ouro, sim, mais do que o ouro fino.", "19:119:128": "Assim, considero corretas todas as tuas instruções; Odeio todo caminho de falsidade.", "19:119:129": "Tuas advertências são maravilhosas. É por isso que eu as acato.", "19:119:130": "A revelação das tuas palavras traz luz, Dando entendimento aos inexperientes.", "19:119:131": "Abro a minha boca e suspiro, Pois anseio pelos teus mandamentos.", "19:119:132": "Volta-te para mim e mostra-me favor, Conforme o teu julgamento para os que amam o teu nome.", "19:119:133": "Guia os meus passos em segurança com a tua declaração; Que nenhum mal me domine.", "19:119:134": "Livra-me da opressão dos homens, E eu cumprirei as tuas ordens.", "19:119:135": "Faz a tua face brilhar sobre o teu servo E ensina-me os teus decretos.", "19:119:136": "Lágrimas escorrem dos meus olhos Porque as pessoas não guardam a tua lei.", "19:119:137": "Tu és justo, ó Jeová, E teus julgamentos são imparciais.", "19:119:138": "As advertências dadas por ti são justas E totalmente confiáveis.", "19:119:139": "Meu zelo me consome, Porque os meus adversários se esqueceram das tuas palavras.", "19:119:140": "Tua declaração é puríssima, E teu servo a ama.", "19:119:141": "Sou insignificante e desprezado; Mesmo assim, não me esqueço das tuas ordens.", "19:119:142": "Tua justiça é justiça eterna, E tua lei é verdade.", "19:119:143": "Embora venha sobre mim aflição e dificuldade, Eu continuo a gostar muito dos teus mandamentos.", "19:119:144": "A justiça das tuas advertências é eterna. Dá-me entendimento, para que eu continue vivendo.", "19:119:145": "Clamo de todo o coração. Responde-me, ó Jeová. Vou cumprir os teus decretos.", "19:119:146": "Invoco a ti; salva-me! Vou guardar as tuas advertências.", "19:119:147": "Desperto antes do amanhecer para clamar por ajuda, Pois as tuas palavras são a minha esperança.", "19:119:148": "Meus olhos se abrem antes das vigílias da noite, Para eu meditar na tua declaração.", "19:119:149": "Ouve a minha voz por causa do teu amor leal. Ó Jeová, preserva-me vivo em harmonia com a tua justiça.", "19:119:150": "Aproximam-se os que se envolvem em conduta vergonhosa; Eles estão longe da tua lei.", "19:119:151": "Tu estás perto, ó Jeová, E todos os teus mandamentos são verdade.", "19:119:152": "Há muito tempo aprendi sobre as tuas advertências, Que tu as estabeleceste para durarem para sempre.", "19:119:153": "Olha para a minha aflição e socorre-me, Pois não me esqueço da tua lei.", "19:119:154": "Defende-me e livra-me; Preserva-me vivo, em harmonia com a tua promessa.", "19:119:155": "A salvação está longe dos maus, Porque eles não buscam os teus decretos.", "19:119:156": "Tua misericórdia é grande, ó Jeová. Preserva-me vivo, em harmonia com a tua justiça.", "19:119:157": "Muitos são os meus perseguidores e adversários; Mas eu não me desvio das tuas advertências.", "19:119:158": "Olho com repugnância para os traiçoeiros, Porque não guardam a tua declaração.", "19:119:159": "Vê como eu amo as tuas ordens! Ó Jeová, preserva-me vivo por causa do teu amor leal.", "19:119:160": "A verdade é a própria essência da tua palavra, E todos os teus julgamentos justos duram para sempre.", "19:119:161": "Príncipes me perseguem sem nenhum motivo, Mas o meu coração tem reverência pelas tuas palavras.", "19:119:162": "Alegro-me por causa da tua declaração Como alguém que acha muito despojo.", "19:119:163": "Odeio a falsidade, eu a detesto. Eu amo a tua lei.", "19:119:164": "Eu te louvo sete vezes por dia Por causa dos teus julgamentos justos.", "19:119:165": "Os que amam a tua lei têm grande paz; Nada pode fazê-los tropeçar.", "19:119:166": "Espero por teus atos de salvação, ó Jeová, E obedeço aos teus mandamentos.", "19:119:167": "Guardo as tuas advertências, E eu as amo profundamente.", "19:119:168": "Obedeço às tuas ordens e às tuas advertências, Pois sabes tudo que faço.", "19:119:169": "Chegue a ti o meu clamor por ajuda, ó Jeová. Dá-me entendimento, de acordo com a tua palavra.", "19:119:170": "Chegue a ti o meu pedido de favor. Salva-me, conforme prometeste.", "19:119:171": "Que os meus lábios transbordem de louvor, Pois tu me ensinas os teus decretos.", "19:119:172": "Que a minha língua cante a tua declaração, Pois todos os teus mandamentos são justos.", "19:119:173": "Que a tua mão esteja pronta para me ajudar, Pois escolhi obedecer às tuas ordens.", "19:119:174": "Anseio pela tua salvação, ó Jeová, E gosto muito da tua lei.", "19:119:175": "Deixa-me viver, para que eu possa te louvar; Que as tuas decisões judiciais sejam a minha ajuda.", "19:119:176": "Afastei-me como uma ovelha perdida. Vem procurar o teu servo, Pois não me esqueci dos teus mandamentos.", "20:1:1": "Provérbios de Salomão, filho de Davi, rei de Israel:", "20:1:2": "Para aprender sabedoria e disciplina; Para entender declarações profundas;", "20:1:3": "Para obter a disciplina que dá entendimento, Justiça, bom critério e retidão;", "20:1:4": "Para dar prudência aos inexperientes; Para dar conhecimento e raciocínio aos jovens.", "20:1:5": "O sábio escuta e assimila mais instrução; O homem que tem entendimento obtém orientação perita", "20:1:6": "Para entender provérbios e declarações intrigantes, As palavras dos sábios e os seus enigmas.", "20:1:7": "O temor de Jeová é o princípio do conhecimento. Apenas os tolos desprezam a sabedoria e a disciplina.", "20:1:8": "Escute, meu filho, a disciplina do seu pai E não abandone a instrução da sua mãe.", "20:1:9": "Pois são uma linda coroa de flores para a sua cabeça E um belo adorno para o seu pescoço.", "20:1:10": "Meu filho, se pecadores tentarem seduzi-lo, não se deixe levar por eles.", "20:1:11": "Se disserem: “Venha conosco. Vamos armar uma emboscada para derramar sangue. Fiquemos escondidos à espera de vítimas inocentes, só para nos divertir.", "20:1:12": "Vamos devorá-los vivos, como faz a Sepultura, Inteiros, como os que descem à cova.", "20:1:13": "Vamos tomar todos os seus preciosos tesouros; Encheremos as nossas casas com despojo.", "20:1:14": "Você devia se juntar a nós, E todos repartiremos por igual o que roubarmos”,", "20:1:15": "Não vá atrás deles, meu filho. Mantenha seus pés longe do caminho deles,", "20:1:16": "Pois os pés deles correm para fazer o mal; Eles se apressam em derramar sangue.", "20:1:17": "Com certeza é inútil estender uma rede quando o pássaro está olhando.", "20:1:18": "É por isso que eles ficam de emboscada para derramar sangue; Ficam escondidos para tirar a vida de outros.", "20:1:19": "Esses são os caminhos dos que procuram lucro desonesto, Que acaba tirando a vida dos que o obtêm.", "20:1:20": "A verdadeira sabedoria grita nas ruas. Ergue a sua voz nas praças.", "20:1:21": "Clama na esquina das ruas movimentadas. Na entrada dos portões da cidade, ela diz:", "20:1:22": "“Até quando vocês, inexperientes, amarão a inexperiência? Até quando vocês, zombadores, terão prazer na zombaria? Até quando vocês, tolos, odiarão o conhecimento?", "20:1:23": "Acatem a minha repreensão, Então derramarei o meu espírito em seu benefício; Vou fazê-los conhecer as minhas palavras.", "20:1:24": "Eu chamei, mas vocês se negaram a ouvir; Estendi a mão, mas ninguém deu atenção.", "20:1:25": "Vocês desconsideraram todos os meus conselhos E rejeitaram a minha repreensão;", "20:1:26": "Por isso, vou rir da sua desgraça, Vou zombar quando acontecer aquilo que vocês temem,", "20:1:27": "Quando aquilo que vocês temem vier como uma tempestade, E a sua desgraça chegar como um vendaval, Quando vierem sobre vocês aflição e dificuldades.", "20:1:28": "Naquele tempo eles me chamarão, mas eu não responderei; Procurarão ansiosamente por mim, mas não me acharão,", "20:1:29": "Porque odiaram o conhecimento E não quiseram temer a Jeová.", "20:1:30": "Não aceitaram os meus conselhos; Eles desconsideraram todas as minhas repreensões.", "20:1:31": "Portanto, sofrerão as consequências do seu proceder E ficarão empanturrados com os seus próprios planos.", "20:1:32": "Pois a rebeldia dos inexperientes os matará, E a despreocupação dos tolos os destruirá.", "20:1:33": "Mas quem me escuta residirá em segurança E ficará tranquilo, sem temer nenhuma calamidade.”", "20:3:1": "Meu filho, não se esqueça dos meus ensinamentos, E que o seu coração obedeça aos meus mandamentos,", "20:3:2": "Porque eles lhe acrescentarão muitos dias E anos de vida e paz.", "20:3:3": "Que o amor leal e a fidelidade não o abandonem. Coloque-os em volta do pescoço; Escreva-os na tábua do seu coração;", "20:3:4": "Então você ganhará favor e terá grande entendimento Aos olhos de Deus e dos homens.", "20:3:5": "Confie em Jeová de todo o seu coração; Não confie no seu próprio entendimento.", "20:3:6": "Lembre-se dele em todos os seus caminhos, E ele endireitará as suas veredas.", "20:3:7": "Não se torne sábio aos seus próprios olhos. Tema a Jeová e afaste-se do mal.", "20:3:8": "Isso será uma cura para o seu corpo E revigoramento para os seus ossos.", "20:3:9": "Honre a Jeová com as suas coisas valiosas, Com as primícias de todas as suas colheitas;", "20:3:10": "Então os seus celeiros ficarão completamente cheios, E os seus tanques de vinho novo transbordarão.", "20:3:11": "Meu filho, não rejeite a disciplina de Jeová, E não abomine a sua repreensão,", "20:3:12": "Pois Jeová repreende aqueles a quem ama, Assim como o pai faz com um filho querido.", "20:3:13": "Feliz o homem que acha sabedoria E o homem que obtém discernimento;", "20:3:14": "Ganhar sabedoria é melhor do que ganhar prata, E obtê-la é melhor do que obter ouro.", "20:3:15": "Ela é mais preciosa do que corais; Nada do que você deseja pode se comparar a ela.", "20:3:16": "Na sua mão direita há vida longa; Na esquerda, riquezas e glória.", "20:3:17": "Seus caminhos são agradáveis, E todas as suas veredas são pacíficas.", "20:3:18": "Ela é árvore de vida para os que se apegam a ela, E os que a agarram serão considerados felizes.", "20:3:19": "Jeová lançou os alicerces da terra com sabedoria. Estabeleceu firmemente os céus com discernimento.", "20:3:20": "Pelo seu conhecimento as águas profundas se partiram, E as nuvens destilaram orvalho.", "20:3:21": "Meu filho, não perca essas coisas de vista. Resguarde a sabedoria prática e o raciocínio;", "20:3:22": "Eles lhe darão vida E serão um adorno para o seu pescoço.", "20:3:23": "Assim você andará em segurança no seu caminho, E o seu pé nunca tropeçará.", "20:3:24": "Quando você se deitar, não terá medo; Você se deitará, e o seu sono será agradável.", "20:3:25": "Você não terá medo de nenhum terror repentino, Nem da tempestade que está vindo sobre os maus.", "20:3:26": "Pois Jeová será a sua fonte de confiança, Ele protegerá o seu pé da armadilha.", "20:3:27": "Não deixe de fazer o bem a quem você deve fazê-lo, Se estiver ao seu alcance ajudar.", "20:3:28": "Não diga ao seu próximo: “Vá embora, volte depois! Eu lhe darei algo amanhã”, Se você pode dar algo agora.", "20:3:29": "Não planeje prejudicar o seu próximo, Que mora ao seu lado e confia em você.", "20:3:30": "Não entre em conflito com um homem sem motivo, Se ele não lhe fez nada de mau.", "20:3:31": "Não fique com inveja do homem violento, Nem escolha nenhum dos seus caminhos,", "20:3:32": "Pois Jeová detesta a pessoa falsa, Mas tem amizade íntima com os íntegros.", "20:3:33": "A maldição de Jeová está sobre a casa dos maus, Mas ele abençoa o lar dos justos.", "20:3:34": "Pois ele zomba dos zombadores, Mas mostra favor aos mansos.", "20:3:35": "Os sábios herdarão a honra, Mas os tolos exaltam a desonra.", "20:14:1": "A mulher realmente sábia edifica a sua casa, Mas a tola a derruba com as próprias mãos.", "20:14:2": "Quem anda na sua retidão teme a Jeová, Mas quem segue caminhos sinuosos o despreza.", "20:14:3": "A vara da arrogância está na boca dos tolos, Mas os lábios dos sábios os protegerão.", "20:14:4": "Onde não há bois, a manjedoura fica limpa; Mas a força do touro produz uma colheita abundante.", "20:14:5": "A testemunha fiel não mente, Mas a testemunha falsa só fala mentiras.", "20:14:6": "O zombador procura sabedoria, e não acha nenhuma, Mas o conhecimento vem facilmente para quem tem entendimento.", "20:14:7": "Fique longe do homem tolo, Pois em seus lábios você não encontrará conhecimento.", "20:14:8": "A sabedoria faz o homem prudente entender seu caminho, Mas os insensatos são enganados pela sua tolice.", "20:14:9": "Os tolos riem da culpa, Mas entre os justos há disposição de fazer as pazes.", "20:14:10": "Cada coração conhece sua própria amargura, E mais ninguém pode participar da sua alegria.", "20:14:11": "A casa dos maus será destruída, Mas a tenda dos justos florescerá.", "20:14:12": "Há um caminho que parece certo ao homem, Mas por fim leva à morte.", "20:14:13": "Mesmo no riso, o coração talvez sinta dor; E a alegria pode acabar em tristeza.", "20:14:14": "Quem é rebelde no coração colherá as consequências dos seus caminhos, Mas o homem bom colhe a recompensa das suas ações.", "20:14:15": "A pessoa ingênua acredita em qualquer palavra, Mas quem é prudente pensa bem antes de cada passo.", "20:14:16": "O sábio é cauteloso e se afasta do mal, Mas o tolo é imprudente e autoconfiante.", "20:14:17": "Quem se ira facilmente comete tolices, Mas o homem de reflexão é odiado.", "20:14:18": "Os ingênuos herdarão a tolice, Mas os prudentes são coroados com o conhecimento.", "20:14:19": "Os maus terão de se curvar diante dos bons, E os perversos se curvarão diante dos portões dos justos.", "20:14:20": "O pobre é odiado até pelo seu próximo, Mas muitos são os amigos do rico.", "20:14:21": "Quem despreza o seu próximo comete um pecado, Mas quem tem compaixão dos humildes é feliz.", "20:14:22": "Por acaso não se perderão os que tramam a maldade? Mas os que estão decididos a fazer o bem encontrarão amor leal e fidelidade.", "20:14:23": "Há proveito em todo tipo de trabalho árduo, Mas ficar só falando leva à pobreza.", "20:14:24": "A coroa dos sábios é a sua riqueza, Mas a tolice dos tolos não passa de tolice.", "20:14:25": "A testemunha verdadeira salva vidas, Mas a falsa só fala mentiras.", "20:14:26": "No temor de Jeová o homem encontra forte confiança E um refúgio para os seus filhos.", "20:14:27": "O temor de Jeová é fonte de vida E desvia dos laços da morte.", "20:14:28": "Um povo numeroso é a glória do rei, Mas um governante sem súditos está arruinado.", "20:14:29": "Quem não se ira facilmente tem muito discernimento, Mas quem é impaciente demonstra sua tolice.", "20:14:30": "O coração calmo é vida para o corpo, Mas o ciúme é podridão para os ossos.", "20:14:31": "Quem defrauda o humilde insulta Aquele que o fez, Mas quem tem compaixão do pobre O glorifica.", "20:14:32": "Quem é mau será derrubado pela sua própria maldade, Mas o justo se refugiará na sua integridade.", "20:14:33": "A sabedoria descansa sem alarde no coração dos que têm entendimento, Mas os tolos têm de exibi-la.", "20:14:34": "A justiça enaltece uma nação, Mas o pecado é uma vergonha para um povo.", "20:14:35": "O rei tem prazer no servo que age com perspicácia, Mas fica furioso com aquele que age vergonhosamente.", "20:15:1": "Uma resposta branda acalma o furor, Mas uma palavra dura atiça a ira.", "20:15:2": "A língua dos sábios faz bom uso do conhecimento, Mas a boca dos tolos jorra tolice.", "20:15:3": "Os olhos de Jeová estão em todo lugar, Vigiando tanto os maus como os bons.", "20:15:4": "A língua calma é árvore de vida, Mas a palavra perversa causa profunda tristeza.", "20:15:5": "O tolo desrespeita a disciplina do pai, Mas quem é prudente aceita correção.", "20:15:6": "Na casa do justo há muitos tesouros, Mas o fruto do trabalho de quem é mau lhe causa dificuldades.", "20:15:7": "Os lábios dos sábios espalham conhecimento, Mas o coração dos tolos não é assim.", "20:15:8": "O sacrifício dos maus é detestável para Jeová, Mas a oração dos justos é um prazer para ele.", "20:15:9": "Jeová detesta o caminho de quem é mau, Mas ama quem se empenha pela justiça.", "20:15:10": "A disciplina parece ruim para quem abandona o caminho, Mas quem odeia a repreensão morrerá.", "20:15:11": "A Sepultura e o lugar de destruição estão diante dos olhos de Jeová. Quanto mais o coração dos homens!", "20:15:12": "O zombador não gosta daquele que o corrige; Ele não consulta os sábios.", "20:15:13": "O coração alegre ilumina o rosto, Mas o coração angustiado deixa o espírito abatido.", "20:15:14": "O coração sábio busca conhecimento, Mas a boca dos tolos se alimenta de tolice.", "20:15:15": "Para o aflito, todos os dias são maus, Mas quem é alegre de coração tem sempre um banquete.", "20:15:16": "Melhor o pouco com o temor de Jeová Do que muita riqueza com ansiedade.", "20:15:17": "Melhor um prato de verduras onde há amor Do que um boi gordo onde há ódio.", "20:15:18": "O homem que se irrita facilmente provoca briga, Mas quem é paciente acalma a discussão.", "20:15:19": "O caminho do preguiçoso é cheio de espinhos, Mas a vereda dos justos é uma estrada plana.", "20:15:20": "O filho sábio alegra seu pai, Mas o homem tolo despreza sua mãe.", "20:15:21": "A tolice alegra quem não tem bom senso, Mas o homem de discernimento caminha direito.", "20:15:22": "Os planos fracassam quando não há comunicação, Mas com muitos conselheiros há bons resultados.", "20:15:23": "O homem se alegra ao dar uma resposta certa, E como é boa uma palavra no tempo certo!", "20:15:24": "O caminho da vida conduz para cima quem tem perspicácia, Para afastá-lo da Sepultura lá embaixo.", "20:15:25": "Jeová derrubará a casa dos arrogantes, Mas protegerá os limites da propriedade da viúva.", "20:15:26": "Jeová detesta as tramas de quem é mau, Mas declarações agradáveis são puras para Ele.", "20:15:27": "Quem obtém lucro desonesto causa dificuldades à sua própria casa, Mas quem odeia o suborno continuará vivo.", "20:15:28": "O coração do justo medita antes de responder, Mas a boca dos maus jorra coisas más.", "20:15:29": "Jeová está longe dos maus, Mas ouve a oração dos justos.", "20:15:30": "Olhos radiantes alegram o coração; Uma boa notícia revigora os ossos.", "20:15:31": "Quem escuta a repreensão que dá vida Habita entre os sábios.", "20:15:32": "Quem rejeita a disciplina despreza a sua vida, Mas quem escuta a repreensão obtém entendimento.", "20:15:33": "O temor de Jeová ensina a pessoa a ser sábia, E antes da glória vem a humildade.", "21:7:1": "Um bom nome é melhor do que um bom óleo, e o dia da morte é melhor do que o dia do nascimento.", "21:7:2": "Melhor é ir a uma casa onde há luto do que ir a uma casa onde há festa, pois a morte é o fim de todo homem, e quem está vivo deve refletir sobre isso.", "21:7:3": "Melhor a tristeza do que o riso, pois um rosto triste torna melhor o coração.", "21:7:4": "O coração dos sábios está na casa onde há luto, mas o coração dos tolos está na casa onde há alegria.", "21:7:5": "Melhor é ouvir a censura de um sábio do que ouvir a canção dos tolos.", "21:7:6": "Pois, igual ao estalar de espinhos queimando debaixo da panela, assim é o riso do tolo; e isso também é vaidade.", "21:7:7": "Mas a opressão pode levar o sábio à loucura, e o suborno corrompe o coração.", "21:7:8": "Melhor é o fim de uma coisa do que o seu começo. Melhor é ser paciente do que ter um espírito arrogante.", "21:7:9": "Não fique ofendido facilmente, pois é o coração dos tolos que fica ofendido.", "21:7:10": "Não diga: “Por que os tempos antigos eram melhores do que os atuais?” Pois não é a sabedoria que o faz perguntar isso.", "21:7:11": "A sabedoria acompanhada de uma herança é algo bom, e é uma vantagem para os que veem a luz do dia.", "21:7:12": "Pois a sabedoria é uma proteção, assim como o dinheiro é uma proteção. Mas a vantagem do conhecimento é esta: a sabedoria preserva a vida de quem a possui.", "21:7:13": "Considere o trabalho do verdadeiro Deus: quem pode endireitar o que ele fez torto?", "21:7:14": "Num dia bom seja bom também; mas, num dia de dificuldades, lembre-se de que o verdadeiro Deus fez tanto um como o outro, de modo que os homens não podem ter certeza de nada do que lhes acontecerá no futuro.", "21:7:15": "Durante a minha vida vã, vi de tudo: pessoas justas que morrem na sua justiça e pessoas más que vivem muito tempo, apesar da sua maldade.", "21:7:16": "Não seja justo demais nem excessivamente sábio. Por que deveria causar ruína a si mesmo?", "21:7:17": "Não seja excessivamente mau, nem seja tolo. Por que deveria morrer antes do seu tempo?", "21:7:18": "É melhor seguir um dos conselhos, mas não desconsiderar o outro; pois quem teme a Deus acatará a ambos.", "21:7:19": "A sabedoria faz com que o sábio seja mais poderoso do que dez homens fortes numa cidade.", "21:7:20": "Pois não há nenhum homem justo na terra que sempre faça o que é bom e nunca peque.", "21:7:21": "Também, não dê atenção a todas as palavras que as pessoas dizem, senão você poderia ouvir seu servo amaldiçoá-lo;", "21:7:22": "pois você, no íntimo, bem sabe que você mesmo, muitas vezes, amaldiçoou a outros.", "21:7:23": "Tudo isso eu examinei com sabedoria, e eu disse: “Vou me tornar sábio.” Mas isso estava fora do meu alcance.", "21:7:24": "O que já aconteceu é inatingível e insondável. Quem o pode entender?", "21:7:25": "Eu voltei meu coração para conhecer, investigar e procurar a sabedoria e a razão por trás das coisas, e para entender a maldade da insensatez e a tolice da loucura.", "21:7:26": "Então descobri que mais amarga do que a morte é a mulher que é como uma rede de caça, cujo coração é como redes de arrasto e cujas mãos são como correntes. Aquele que agrada ao verdadeiro Deus escapará dela, mas o pecador é capturado por ela.", "21:7:27": "“Veja, isto é o que eu descobri”, diz o congregante. “Investiguei uma coisa após outra para tirar uma conclusão,", "21:7:28": "mas, o que busquei continuamente, não encontrei. Entre mil, achei um homem, mas não achei nenhuma mulher.", "21:7:29": "O que descobri se resume nisto: o verdadeiro Deus fez a humanidade reta, mas eles seguiram seus próprios planos.”", "23:48:1": "Ouçam isto, ó casa de Jacó, Vocês que chamam a si mesmos pelo nome de Israel E que procederam das águas de Judá, Vocês que juram pelo nome de Jeová E invocam o Deus de Israel, Mas não com sinceridade e retidão.", "23:48:2": "Pois chamam a si mesmos pelo nome da cidade santa E buscam o apoio do Deus de Israel, Cujo nome é Jeová dos exércitos.", "23:48:3": "“Eu lhes anunciei há muito tempo as coisas que já aconteceram, Elas saíram da minha própria boca; Eu as divulguei. De repente eu agi, e elas se realizaram.", "23:48:4": "Visto que eu sabia que você é obstinado, Que o seu pescoço é um tendão de ferro e que a sua testa é de cobre,", "23:48:5": "Eu o informei há muito tempo. Antes que as coisas acontecessem, eu as revelava, Para que você não dissesse: ‘Foi o meu ídolo que fez isso; Foi a minha imagem esculpida e a minha imagem de metal que ordenaram essas coisas.’", "23:48:6": "Você ouviu e viu tudo isso; Não o dirá a outros? De agora em diante eu lhe anuncio coisas novas, Coisas mantidas em segredo, que você não sabia.", "23:48:7": "Somente agora elas estão sendo criadas, não foram criadas há muito tempo. Até hoje você nunca tinha ouvido falar dessas coisas, De modo que você não pode dizer: ‘Eu já sabia disso!’", "23:48:8": "Não, você não ouviu, você não sabia, E no passado você manteve os ouvidos fechados. Pois eu sei que você é muito traiçoeiro, E foi chamado de transgressor desde o nascimento.", "23:48:9": "Mas por causa do meu nome controlarei a minha ira; Para o meu próprio louvor eu me refrearei, E não o eliminarei.", "23:48:10": "Veja! Eu o refinei, mas não como se faz com a prata. Eu o provei na fornalha da aflição.", "23:48:11": "Por minha causa, sim, por minha própria causa agirei. Pois como eu poderia me deixar profanar? Não dou a minha glória a nenhum outro.", "23:48:12": "Escute-me, ó Jacó, e Israel, a quem chamei. Eu sou o mesmo. Sou o primeiro e também sou o último.", "23:48:13": "A minha própria mão lançou o alicerce da terra, E a minha mão direita estendeu os céus. Quando eu os chamo, todos eles se apresentam.", "23:48:14": "Reúnam-se, todos vocês, e ouçam. Quem entre eles anunciou essas coisas? Aquele a quem Jeová amou Fará com Babilônia o que for do Seu agrado, E o seu braço virá contra os caldeus.", "23:48:15": "Eu mesmo falei e o chamei. Eu o fiz vir, e seu caminho será bem-sucedido.", "23:48:16": "Aproximem-se e ouçam isto. Desde o começo, nunca falei em segredo. Eu estava presente quando as coisas aconteceram.” E agora o Soberano Senhor Jeová enviou tanto a mim como o seu espírito.", "23:48:17": "Assim diz Jeová, seu Resgatador, o Santo de Israel: “Eu, Jeová, sou o seu Deus, Aquele que ensina o que é melhor para você, Aquele que o guia no caminho em que deve andar.", "23:48:18": "Como seria bom se você prestasse atenção aos meus mandamentos! Então a sua paz se tornaria como um rio, E a sua justiça como as ondas do mar.", "23:48:19": "A sua descendência seria como a areia; Os seus descendentes, tão numerosos como os grãos de areia. O nome deles jamais seria eliminado nem apagado de diante de mim.”", "23:48:20": "Saiam de Babilônia! Fujam dos caldeus! Anunciem isso com gritos de alegria! Proclamem-no! Divulguem-no até os confins da terra. Digam: “Jeová resgatou seu servo Jacó.", "23:48:21": "Eles não passaram sede quando os conduziu através de lugares desertos. Ele fez água sair da rocha para eles, Partiu uma rocha e fez jorrar água.”", "23:48:22": "“Não há paz para os que são maus”, diz Jeová.", "23:55:1": "Venham, todos vocês que estão com sede, venham à água! Vocês que não têm dinheiro, venham, comprem e comam! Sim, venham, levem vinho e leite sem dinheiro e sem custo!", "23:55:2": "Por que continuam a gastar dinheiro com o que não é pão, E por que gastam seu salário com o que não traz satisfação? Escutem-me atentamente e comam o que é bom, E vocês saborearão os melhores alimentos.", "23:55:3": "Escutem e venham a mim. Deem ouvidos, e vocês ficarão vivos, E eu sem falta farei com vocês um pacto eterno Em harmonia com as fiéis expressões de amor leal a Davi.", "23:55:4": "Vejam, fiz dele uma testemunha para as nações, Um líder e governante para as nações.", "23:55:5": "Veja, você chamará uma nação que não conhece, E pessoas de uma nação que não o conhecem correrão a você Por causa de Jeová, seu Deus, o Santo de Israel, Porque ele o glorificará.", "23:55:6": "Busquem a Jeová enquanto ele pode ser achado. Chamem-no enquanto ele está perto.", "23:55:7": "Deixem os maus o seu caminho, E os malfeitores os seus pensamentos; Que eles voltem a Jeová, que terá misericórdia deles, Ao nosso Deus, porque perdoará amplamente.", "23:55:8": "“Pois os meus pensamentos não são os seus pensamentos, E os seus caminhos não são os meus caminhos”, diz Jeová.", "23:55:9": "“Pois, assim como os céus são mais altos do que a terra, Assim os meus caminhos são mais altos do que os seus caminhos, E os meus pensamentos, do que os seus pensamentos.", "23:55:10": "Pois, assim como a chuva e a neve descem do céu E não voltam para lá sem antes saturar a terra e fazê-la produzir e brotar, Dando semente aos que semeiam e pão aos que comem,", "23:55:11": "Assim será a palavra que sai da minha boca. Não voltará a mim sem resultados, Mas certamente realizará o que for do meu agrado, E sem falta cumprirá o objetivo para o qual a enviei.", "23:55:12": "Pois vocês sairão com alegria, E serão trazidos em paz. Os montes e as colinas ficarão animados diante de vocês com gritos de alegria, E as árvores do campo baterão palmas.", "23:55:13": "Em lugar dos espinheiros crescerá o junípero, E em lugar da urtiga crescerá a murta. Isso trará glória para Jeová, Será um sinal eterno, que nunca deixará de existir.”", "24:23:1": "“Ai dos pastores que destroem e espalham as ovelhas do meu pasto!” diz Jeová.", "24:23:2": "Portanto, assim diz Jeová, o Deus de Israel, contra os pastores que pastoreiam o meu povo: “Vocês espalharam as minhas ovelhas, vocês as dispersaram e não voltaram a sua atenção para elas.” “Portanto, voltarei a minha atenção para vocês por causa das suas más ações”, diz Jeová.", "24:23:3": "“Depois reunirei o restante das minhas ovelhas dentre todas as terras às quais eu as espalhei, e vou trazê-las de volta à sua pastagem, e elas se reproduzirão e se tornarão muitas.", "24:23:4": "E vou colocar sobre elas pastores que realmente as pastorearão. Elas não terão mais medo, nem ficarão apavoradas, e nenhuma delas se perderá”, diz Jeová.", "24:23:5": "“Vejam! Estão chegando os dias”, diz Jeová, “em que farei surgir para Davi um renovo justo. E um rei reinará; ele mostrará entendimento e defenderá a justiça e a retidão no país.", "24:23:6": "Nos seus dias, Judá será salvo e Israel residirá em segurança. E este é o nome pelo qual ele será chamado: Jeová É a Nossa Justiça.”", "24:23:7": "“Contudo, estão chegando os dias”, diz Jeová, “em que não dirão mais: ‘Tão certo como vive Jeová, aquele que tirou o povo de Israel da terra do Egito!’", "24:23:8": "mas sim: ‘Tão certo como vive Jeová, aquele que tirou e trouxe de volta os descendentes da casa de Israel da terra do norte e de todas as terras às quais eu os havia espalhado’, e eles morarão na sua própria terra.”", "24:23:9": "Sobre os profetas: Meu coração está quebrantado dentro de mim. Todos os meus ossos estão tremendo. Pareço um homem bêbado, Um homem vencido pelo vinho, Por causa de Jeová e das suas santas palavras.", "24:23:10": "Pois esta terra está cheia de adúlteros; Por causa da maldição, esta terra ficou de luto, E as pastagens do deserto secaram. Seu modo de agir é mau, e eles abusam do poder que têm.", "24:23:11": "“Tanto os profetas como os sacerdotes são impuros. Até na minha própria casa encontrei a maldade deles”, diz Jeová.", "24:23:12": "“Por isso, seu caminho se tornará escorregadio e escuro; Eles serão empurrados e cairão. Pois trarei sobre eles calamidade No ano do ajuste de contas”, diz Jeová.", "24:23:13": "“Entre os profetas de Samaria, eu vi algo repugnante: Suas profecias são da parte de Baal, E eles desencaminham o meu povo Israel.", "24:23:14": "E, entre os profetas de Jerusalém, eu vi coisas horríveis: Eles cometem adultério e vivem na mentira, Apoiam os malfeitores E não abandonam a sua maldade. Para mim, todos eles são como Sodoma, E os habitantes dela são como Gomorra.”", "24:23:15": "Portanto, assim diz Jeová dos exércitos contra os profetas: “Vou fazê-los comer absinto E vou dar-lhes água envenenada para beber. Pois os profetas de Jerusalém espalharam a apostasia por todo o país.”", "24:23:16": "Assim diz Jeová dos exércitos: “Não escutem as palavras dos profetas que profetizam para vocês. Eles estão iludindo vocês. Falam das visões que vêm do seu próprio coração, Não da boca de Jeová.", "24:23:17": "Dizem vez após vez aos que me desrespeitam: ‘Jeová disse: “Vocês terão paz.”’ E a todos os que seguem o seu próprio coração obstinado, eles dizem: ‘Nenhuma calamidade virá sobre vocês.’", "24:23:18": "Mas quem faz parte do grupo íntimo de Jeová Para observar e acatar a sua palavra? Quem prestou atenção à sua palavra e obedeceu a ela?", "24:23:19": "Vejam! O vendaval da parte de Jeová irromperá com fúria; Como um tufão, será lançado sobre a cabeça dos maus.", "24:23:20": "A ira de Jeová não recuará Até que ele tenha cumprido e executado as intenções do seu coração. Na parte final dos dias, vocês entenderão isso claramente.", "24:23:21": "Não enviei esses profetas, mesmo assim eles foram correndo. Não falei com eles, mesmo assim eles profetizaram.", "24:23:22": "Mas, se eles fizessem parte do meu grupo íntimo, Teriam feito o meu povo ouvir as minhas palavras E os teriam levado a recuar do seu mau caminho e das suas más ações.”", "24:23:23": "“Será que eu sou apenas um Deus de perto”, diz Jeová, “e não também um Deus de longe?”", "24:23:24": "“Será que algum homem pode se esconder num lugar onde eu não o veja?” diz Jeová. “Por acaso eu não ocupo os céus e a terra?” diz Jeová.", "24:23:25": "“Eu ouvi os profetas que profetizam mentiras em meu nome. Eles dizem: ‘Tive um sonho! Tive um sonho!’", "24:23:26": "Até quando profetizar mentiras continuará no coração dos profetas? Eles profetizam as mentiras do seu próprio coração.", "24:23:27": "Com os sonhos que contam uns aos outros, eles querem fazer o meu povo se esquecer do meu nome, assim como os seus pais se esqueceram do meu nome por causa de Baal.", "24:23:28": "Que o profeta que tem um sonho conte o seu sonho, mas que aquele que tem a minha palavra fale a minha palavra fielmente.” “O que a palha tem a ver com o grão?” diz Jeová.", "24:23:29": "“Não é a minha palavra como um fogo”, diz Jeová, “e como um martelo que despedaça o rochedo?”", "24:23:30": "“Por isso, eu estou contra os profetas”, diz Jeová, “aqueles que roubam as minhas palavras uns dos outros”.", "24:23:31": "“Eu estou contra os profetas”, diz Jeová, “aqueles que usam a língua para dizer: ‘Assim Ele diz!’”", "24:23:32": "“Eu estou contra os profetas de sonhos falsos”, diz Jeová, “aqueles que os relatam e desencaminham o meu povo com as suas mentiras e a sua arrogância”. “Mas eu não os enviei nem lhes dei ordem alguma. Portanto, eles não serão de nenhum proveito para este povo”, diz Jeová.", "24:23:33": "“Quando alguém do povo, ou um profeta ou um sacerdote lhe perguntar: ‘Qual é o fardo de Jeová?’ então responda-lhes: ‘“Vocês é que são o fardo! E eu me livrarei de vocês”, diz Jeová.’", "24:23:34": "Quanto ao profeta, ao sacerdote ou a alguém do povo que diz: ‘Este é o fardo de Jeová!’ eu me voltarei contra esse homem e contra os da sua casa.", "24:23:35": "Cada um de vocês pergunta o seguinte ao seu amigo e ao seu irmão: ‘O que Jeová respondeu? O que Jeová disse?’", "24:23:36": "Mas não falem mais sobre o fardo de Jeová, pois o fardo é a palavra de cada um, e vocês mudaram as palavras do Deus vivente, Jeová dos exércitos, o nosso Deus.", "24:23:37": "“Isto é o que você dirá aos profetas: ‘Que resposta Jeová lhe deu? O que Jeová disse?", "24:23:38": "E, se vocês continuarem a dizer: “O fardo de Jeová!”, assim diz Jeová: “Visto que vocês dizem: ‘Esta palavra é o fardo de Jeová’, depois de eu lhes ter ordenado: ‘Não digam: “O fardo de Jeová!”’,", "24:23:39": "então eu os levantarei e os lançarei para longe de mim, tanto vocês como a cidade que dei a vocês e aos seus antepassados.", "24:23:40": "E trarei sobre vocês desonra e humilhação eternas, que nunca serão esquecidas.”’”", "33:7:1": "Ai de mim! Sou como quem, Depois de colher as frutas de verão E de recolher as uvas que sobram após a colheita, Não encontra nenhum cacho de uvas para comer, Nenhum figo temporão que tanto deseja.", "33:7:2": "Desapareceu da terra quem é leal; Não há ninguém que seja reto entre os homens. Todos eles ficam de emboscada para derramar sangue. Cada um caça seu próprio irmão com uma rede.", "33:7:3": "Suas mãos são peritas em fazer o que é mau; O príncipe faz exigências, O juiz julga por suborno, O homem de destaque torna conhecido o que ele quer, E eles planejam isso juntos.", "33:7:4": "O melhor entre eles é como espinhos, O mais reto deles é pior do que uma cerca de espinhos. Chegará o dia anunciado pelos seus vigias e o dia do seu ajuste de contas. Então todos ficarão em pânico.", "33:7:5": "Não tenham fé no seu companheiro Nem confiem num amigo íntimo. Tome cuidado com o que você diz àquela que se deita nos seus braços.", "33:7:6": "Pois o filho despreza o pai, A filha se levanta contra a mãe, E a nora fica contra a sogra; Os inimigos do homem são os homens da sua casa.", "33:7:7": "Mas, quanto a mim, ficarei vigilante esperando por Jeová. Esperarei pacientemente pelo Deus da minha salvação. Meu Deus me ouvirá.", "33:7:8": "Não se alegre por minha causa, ó inimiga minha. Embora eu tenha caído, eu me levantarei; Embora eu more na escuridão, Jeová será minha luz.", "33:7:9": "Suportarei o furor de Jeová — Pois pequei contra ele — Até que ele defenda a minha causa e me faça justiça. Ele me levará para a luz; Verei a sua justiça.", "33:7:10": "Minha inimiga também verá isso, E a vergonha cobrirá aquela que me disse: “Onde está Jeová, seu Deus?” Meus olhos a verão. Então ela será pisoteada como lama nas ruas.", "33:7:11": "Será um dia para construir seus muros de pedras; Naquele dia o limite será estendido.", "33:7:12": "Naquele dia virão a você Da Assíria e das cidades do Egito, Desde o Egito até o rio; De mar a mar e de monte a monte.", "33:7:13": "E a terra ficará desolada por causa dos seus habitantes, Por causa do que eles fizeram.", "33:7:14": "Com o teu bastão pastoreia o teu povo, o rebanho da tua herança, Que morava sozinho numa floresta, no meio de um pomar. Que eles pastem em Basã e Gileade como nos tempos antigos.", "33:7:15": "“Como nos dias em que você saiu da terra do Egito, Eu lhe mostrarei coisas maravilhosas.", "33:7:16": "Nações as verão e ficarão envergonhadas apesar de todo o poder que têm. Porão a mão sobre a boca; Seus ouvidos ficarão surdos.", "33:7:17": "Lamberão o pó como serpentes; Como os répteis da terra, sairão tremendo dos seus refúgios. Virão apavoradas a Jeová, nosso Deus, E terão medo de ti.”", "33:7:18": "Quem é Deus como tu, Que perdoa o erro e deixa passar a transgressão do restante da sua herança? Ele não continuará irado para sempre, Pois tem prazer no amor leal.", "33:7:19": "Ele novamente terá misericórdia de nós; vencerá os nossos erros. Tu lançarás nas profundezas do mar todos os pecados deles.", "33:7:20": "Demonstrarás fidelidade a Jacó, Amor leal a Abraão, Como juraste aos nossos antepassados desde os tempos antigos.", "40:13:1": "Naquele dia, Jesus saiu da casa e se sentou à beira do mar.", "40:13:2": "E as multidões que se reuniram em volta dele eram tão grandes que ele entrou num barco e se sentou, e toda a multidão ficou na praia.", "40:13:3": "Falou-lhes então muitas coisas por meio de ilustrações. Ele disse: “Escutem: Um semeador saiu para semear.", "40:13:4": "Ao passo que semeava, algumas sementes caíram à beira da estrada, e vieram as aves e as comeram.", "40:13:5": "Outras caíram em solo rochoso, onde não havia muita terra, e brotaram imediatamente porque o solo não era profundo.", "40:13:6": "Mas, quando o sol se levantou, ficaram queimadas e murcharam, porque não tinham raiz.", "40:13:7": "Outras caíram entre os espinhos, e os espinhos cresceram e as sufocaram.", "40:13:8": "Ainda outras caíram em solo bom e começaram a dar fruto, esta 100 vezes mais, aquela 60 vezes mais, outra 30 vezes mais.", "40:13:9": "Quem tem ouvidos, escute.”", "40:13:10": "Assim, os seus discípulos vieram e lhe perguntaram: “Por que o senhor lhes fala usando ilustrações?”", "40:13:11": "Em resposta, ele disse: “A vocês é concedido entender os segredos sagrados do Reino dos céus, mas a eles não é concedido.", "40:13:12": "Pois àquele que tem, mais será dado, e se fará que ele tenha em abundância; mas, daquele que não tem, até mesmo o que tem será tirado.", "40:13:13": "É por isso que falo a eles usando ilustrações; porque olham, mas olham em vão, e ouvem, mas ouvem em vão, e não compreendem.", "40:13:14": "E está se cumprindo no caso deles a profecia de Isaías, que diz: ‘Vocês realmente ouvirão, mas de modo algum compreenderão; e realmente olharão, mas de modo algum verão.", "40:13:15": "Pois o coração deste povo ficou insensível, eles taparam os ouvidos e fecharam os olhos, para que nunca vissem com os olhos, nem ouvissem com os ouvidos, nem compreendessem com o coração e dessem meia-volta, e eu os curasse.’", "40:13:16": "“No entanto, felizes são os olhos de vocês porque veem e os seus ouvidos porque ouvem.", "40:13:17": "Pois, digo-lhes a verdade: Muitos profetas e homens justos desejaram ver as coisas que vocês estão observando, mas não as viram, e ouvir as coisas que vocês estão ouvindo, mas não as ouviram.", "40:13:18": "“Escutem agora a ilustração do homem que semeou.", "40:13:19": "Quando alguém ouve a palavra do Reino, mas não a entende, vem o Maligno e arranca o que foi semeado no seu coração; essa é a que foi semeada à beira da estrada.", "40:13:20": "A que foi semeada em solo rochoso representa aquele que ouve a palavra e imediatamente a aceita com alegria.", "40:13:21": "Contudo, ele não tem raiz em si mesmo, mas continua por algum tempo e, quando surge dificuldade ou perseguição por causa da palavra, imediatamente tropeça.", "40:13:22": "A que foi semeada entre os espinhos representa aquele que ouve a palavra, mas as ansiedades deste mundo e o poder enganoso das riquezas sufocam a palavra, e ela se torna infrutífera.", "40:13:23": "A que foi semeada em solo bom representa aquele que ouve a palavra e compreende o sentido dela, que realmente dá fruto e produz, este 100 vezes mais, aquele 60 vezes mais, outro 30 vezes mais.”", "40:13:24": "Apresentou-lhes outra ilustração, dizendo: “O Reino dos céus pode ser comparado a um homem que semeou boa semente no seu campo.", "40:13:25": "Enquanto os homens dormiam, seu inimigo veio, semeou joio no meio do trigo e foi embora.", "40:13:26": "Quando a haste cresceu e produziu fruto, apareceu também o joio.", "40:13:27": "Então, os escravos do dono da casa vieram e lhe perguntaram: ‘O senhor não semeou boa semente no seu campo? De onde veio então o joio?’", "40:13:28": "Ele lhes respondeu: ‘Um inimigo, um homem, fez isso.’ Os escravos lhe disseram: ‘O senhor quer então que vamos ajuntar o joio?’", "40:13:29": "Ele disse: ‘Não, pois, ao ajuntarem o joio, poderiam arrancar também o trigo.", "40:13:30": "Deixem ambos crescer juntos até a colheita, e na época da colheita eu direi aos ceifeiros: Ajuntem primeiro o joio e amarrem-no em feixes para ser queimado; depois ajuntem o trigo no meu celeiro.’”", "40:13:31": "Apresentou-lhes outra ilustração, dizendo: “O Reino dos céus é semelhante a um grão de mostarda, que um homem pegou e plantou no seu campo.", "40:13:32": "De fato, essa é a menor de todas as sementes, mas, depois de crescida, é a maior das hortaliças e se torna uma árvore, de modo que as aves do céu vêm e acham abrigo entre os seus ramos.”", "40:13:33": "Contou-lhes outra ilustração: “O Reino dos céus é semelhante ao fermento que uma mulher pegou e misturou com três grandes medidas de farinha, até que a massa inteira ficou fermentada.”", "40:13:34": "Jesus falou tudo isso às multidões por meio de ilustrações. Realmente, nada lhes falava sem ilustração,", "40:13:35": "para que se cumprissem as palavras do profeta, que disse: “Abrirei a minha boca com ilustrações; proclamarei as coisas escondidas desde a fundação.”", "40:13:36": "Então, depois de dispensar as multidões, ele entrou na casa. Seus discípulos se chegaram a ele e disseram: “Explique-nos a ilustração do joio no campo.”", "40:13:37": "Em resposta, ele disse: “O semeador da boa semente é o Filho do Homem;", "40:13:38": "o campo é o mundo. Quanto à boa semente, são os filhos do Reino, mas o joio são os filhos do Maligno,", "40:13:39": "e o inimigo que o semeou é o Diabo. A colheita é o final de um sistema de coisas, e os ceifeiros são os anjos.", "40:13:40": "Portanto, assim como o joio é ajuntado e queimado no fogo, assim será no final do sistema de coisas.", "40:13:41": "O Filho do Homem enviará seus anjos, e eles ajuntarão dentre o seu Reino todas as coisas que causam tropeço e os que praticam o que é contra a lei,", "40:13:42": "e os lançarão na fornalha ardente. Ali é que haverá o seu choro e o ranger dos seus dentes.", "40:13:43": "Naquele tempo, os justos brilharão tão claramente como o sol, no Reino do seu Pai. Quem tem ouvidos, escute.", "40:13:44": "“O Reino dos céus é semelhante a um tesouro escondido no campo, que um homem achou e escondeu novamente; e, na sua alegria, ele foi, vendeu todas as coisas que tinha e comprou aquele campo.", "40:13:45": "“Também, o Reino dos céus é semelhante a um comerciante viajante que buscava pérolas de boa qualidade.", "40:13:46": "Ao achar uma pérola de grande valor, foi, vendeu prontamente todas as coisas que tinha e a comprou.", "40:13:47": "“Também, o Reino dos céus é semelhante a uma rede de arrasto baixada ao mar e que apanhou peixes de todo tipo.", "40:13:48": "Quando ela ficou cheia, arrastaram-na para a praia, sentaram-se e juntaram os peixes bons em recipientes, mas jogaram fora os imprestáveis.", "40:13:49": "Assim será no final do sistema de coisas. Os anjos sairão e separarão os maus dos justos,", "40:13:50": "e os lançarão na fornalha ardente. Ali é que haverá o seu choro e o ranger dos seus dentes.", "40:13:51": "“Compreenderam o sentido de tudo isso?” Eles responderam: “Sim.”", "40:13:52": "Então ele lhes disse: “Sendo assim, todo instrutor público que é ensinado a respeito do Reino dos céus é semelhante a um homem, dono de uma casa, que tira do seu tesouro coisas novas e coisas velhas.”", "40:13:53": "Quando Jesus terminou de contar essas ilustrações, partiu dali.", "40:13:54": "Chegando à sua própria cidade, começou a ensinar ao povo na sinagoga deles, de modo que ficaram maravilhados e disseram: “Onde este homem obteve essa sabedoria e essa habilidade de realizar obras poderosas?", "40:13:55": "Não é este o filho do carpinteiro? Sua mãe não se chama Maria e seus irmãos Tiago, José, Simão e Judas?", "40:13:56": "E não estão todas as suas irmãs conosco? Então, onde ele obteve tudo isso?”", "40:13:57": "Assim, começaram a tropeçar por causa dele. Mas Jesus lhes disse: “Um profeta não fica sem honra a não ser na sua própria terra e na sua própria casa.”", "40:13:58": "E não fez ali muitas obras poderosas, por causa da falta de fé deles.", "40:22:1": "Jesus lhes falou novamente com ilustrações, dizendo:", "40:22:2": "“O Reino dos céus pode ser comparado a um rei que fez uma festa de casamento para o seu filho.", "40:22:3": "Ele mandou seus escravos chamar os convidados à festa de casamento, mas estes não quiseram ir.", "40:22:4": "Mandou novamente outros escravos, dizendo: ‘Digam aos convidados: “Já preparei o banquete; meus touros e meus animais gordos já foram abatidos e tudo está pronto. Venham à festa de casamento.”’", "40:22:5": "Mas os convidados, indiferentes, foram embora, um para seu próprio campo, outro para seu negócio;", "40:22:6": "e os outros agarraram os escravos dele, os maltrataram e os mataram.", "40:22:7": "“O rei ficou furioso e enviou seus exércitos, matou aqueles assassinos e queimou a cidade deles.", "40:22:8": "Depois disse aos seus escravos: ‘A festa de casamento está pronta, mas os convidados não eram dignos.", "40:22:9": "Portanto, vão às estradas que saem da cidade e convidem para a festa de casamento a qualquer um que encontrarem.’", "40:22:10": "Então, esses escravos foram às estradas e reuniram todos os que encontraram, tanto maus como bons, e a sala para a cerimônia do casamento ficou cheia de convidados.", "40:22:11": "“Quando o rei entrou para verificar os convidados, viu um homem que não estava usando roupa de casamento.", "40:22:12": "Disse-lhe, portanto: ‘Amigo, como você entrou aqui sem roupa de casamento?’ Ele ficou sem fala.", "40:22:13": "O rei disse então aos seus servos: ‘Amarrem as mãos e os pés dele, e lancem-no na escuridão lá fora. Ali é que haverá o seu choro e o ranger dos seus dentes.’", "40:22:14": "“Porque há muitos convidados, mas poucos escolhidos.”", "40:22:15": "Então, os fariseus foram embora e fizeram planos para apanhá-lo nas suas palavras.", "40:22:16": "Depois, enviaram-lhe seus discípulos, junto com partidários de Herodes, para lhe dizer: “Instrutor, sabemos que o senhor é verdadeiro e que ensina o caminho de Deus em verdade, e que não busca agradar a homens, pois não olha para a aparência das pessoas.", "40:22:17": "Diga-nos, então: O que acha? É permitido ou não pagar a César o imposto por cabeça?”", "40:22:18": "Mas Jesus, conhecendo a maldade deles, disse: “Hipócritas, por que vocês me põem à prova?", "40:22:19": "Mostrem-me a moeda do imposto.” Trouxeram-lhe um denário.", "40:22:20": "Ele lhes perguntou: “De quem é esta imagem e inscrição?”", "40:22:21": "Responderam: “De César.” Então ele lhes disse: “Portanto, paguem a César o que é de César, mas a Deus o que é de Deus.”", "40:22:22": "Quando ouviram isso, ficaram maravilhados e, deixando-o, foram embora.", "40:22:23": "Naquele dia, os saduceus, que dizem não haver ressurreição, se aproximaram e lhe perguntaram:", "40:22:24": "“Instrutor, Moisés disse: ‘Se um homem morrer sem deixar filhos, o irmão dele deve se casar com a viúva para dar descendência ao seu irmão.’", "40:22:25": "Acontece que havia conosco sete irmãos. O primeiro se casou e morreu, e, visto que não tinha descendente, deixou a sua esposa para o seu irmão.", "40:22:26": "O mesmo aconteceu com o segundo e com o terceiro, e assim com todos os sete.", "40:22:27": "Por último, morreu a mulher.", "40:22:28": "Assim, na ressurreição, de qual dos sete ela será esposa? Pois todos a tiveram como esposa.”", "40:22:29": "Em resposta, Jesus lhes disse: “Vocês estão enganados, porque não conhecem nem as Escrituras, nem o poder de Deus;", "40:22:30": "pois, na ressurreição, os homens não se casam, nem as mulheres são dadas em casamento, mas são como os anjos no céu.", "40:22:31": "A respeito da ressurreição dos mortos, vocês não leram o que lhes foi falado por Deus, que disse:", "40:22:32": "‘Eu sou o Deus de Abraão, o Deus de Isaque e o Deus de Jacó’? Ele é o Deus, não de mortos, mas de vivos.”", "40:22:33": "Ouvindo isso, as multidões ficaram maravilhadas com o seu ensino.", "40:22:34": "Depois que os fariseus ouviram que ele havia silenciado os saduceus, reuniram-se num só grupo.", "40:22:35": "E um deles, perito na Lei, o pôs à prova com uma pergunta:", "40:22:36": "“Instrutor, qual é o maior mandamento da Lei?”", "40:22:37": "Ele lhe disse: “‘Ame a Jeová, seu Deus, de todo o seu coração, de toda a sua alma e de toda a sua mente.’", "40:22:38": "Esse é o maior e primeiro mandamento.", "40:22:39": "O segundo, semelhante a esse, é: ‘Ame o seu próximo como a si mesmo.’", "40:22:40": "Desses dois mandamentos dependem toda a Lei e os Profetas.”", "40:22:41": "Então, enquanto os fariseus estavam reunidos, Jesus lhes perguntou:", "40:22:42": "“O que vocês pensam do Cristo? De quem ele é filho?” Disseram-lhe: “De Davi.”", "40:22:43": "Ele lhes perguntou: “Como é, então, que Davi, sob inspiração, o chama de Senhor, dizendo:", "40:22:44": "‘Jeová disse ao meu Senhor: “Sente-se à minha direita, até que eu ponha os seus inimigos debaixo dos seus pés”’?", "40:22:45": "Então, se Davi o chama de Senhor, como é que ele é seu filho?”", "40:22:46": "E ninguém foi capaz de lhe dizer uma só palavra em resposta e, daquele dia em diante, ninguém se atreveu a lhe fazer mais perguntas.", "40:23:1": "Jesus disse então às multidões e aos seus discípulos:", "40:23:2": "“Os escribas e os fariseus se sentaram no lugar de Moisés.", "40:23:3": "Portanto, façam e cumpram tudo o que eles dizem a vocês, mas não ajam como eles, pois falam, mas não praticam o que dizem.", "40:23:4": "Amarram cargas pesadas e as põem nos ombros dos homens, mas eles mesmos não estão dispostos nem a movê-las com o dedo.", "40:23:5": "Fazem todas as suas obras para serem vistos pelos homens, pois ampliam as caixinhas com textos que usam como proteção e alongam as franjas das suas roupas.", "40:23:6": "Gostam do lugar mais destacado nos banquetes, dos primeiros assentos nas sinagogas,", "40:23:7": "dos cumprimentos nas praças públicas e de ser chamados ‘Rabi’ pelos homens.", "40:23:8": "Mas vocês não sejam chamados ‘Rabi’, pois um só é o seu Instrutor, e todos vocês são irmãos.", "40:23:9": "Além disso, não chamem a ninguém na terra de seu pai, pois um só é o seu Pai, o celestial.", "40:23:10": "Nem sejam chamados de líderes, pois o seu Líder é um só, o Cristo.", "40:23:11": "Mas o maior entre vocês tem de ser o seu servo.", "40:23:12": "Quem se enaltecer será humilhado, e quem se humilhar será enaltecido.", "40:23:13": "“Ai de vocês, escribas e fariseus, hipócritas! Porque fecham o Reino dos céus diante dos homens; pois vocês mesmos não entram, nem deixam entrar os que estão a caminho para entrar.", "40:23:14": "——", "40:23:15": "“Ai de vocês, escribas e fariseus, hipócritas! Porque percorrem o mar e a terra para fazer um prosélito e, quando conseguem, fazem dele merecedor da Geena duas vezes mais do que vocês.", "40:23:16": "“Ai de vocês, guias cegos, que dizem: ‘Se alguém jurar pelo templo, isso não é nada; mas, se alguém jurar pelo ouro do templo, ele está sob obrigação.’", "40:23:17": "Tolos e cegos! Na verdade, o que é maior: o ouro ou o templo que santifica o ouro?", "40:23:18": "Além disso, vocês dizem: ‘Se alguém jurar pelo altar, isso não é nada; mas, se alguém jurar pela dádiva nele, ele está sob obrigação.’", "40:23:19": "Cegos! Na verdade, o que é maior: a dádiva ou o altar que santifica a dádiva?", "40:23:20": "Portanto, quem jura pelo altar está jurando por ele e por todas as coisas sobre ele;", "40:23:21": "e quem jura pelo templo está jurando por ele e por Aquele que habita nele;", "40:23:22": "e quem jura pelo céu está jurando pelo trono de Deus e por Aquele que está sentado nele.", "40:23:23": "“Ai de vocês, escribas e fariseus, hipócritas! Porque dão o décimo da hortelã, do endro e do cominho, mas desconsideram as questões mais importantes da Lei, isto é, a justiça, a misericórdia e a fidelidade. Essas eram as coisas que precisavam ser feitas, mas sem desconsiderar as outras.", "40:23:24": "Guias cegos, que coam o mosquito, mas engolem o camelo!", "40:23:25": "“Ai de vocês, escribas e fariseus, hipócritas! Porque limpam por fora o copo e o prato, mas por dentro eles estão cheios de ganância e de imoderação.", "40:23:26": "Fariseu cego, limpe primeiro a parte de dentro do copo e do prato, para que a parte de fora também fique limpa.", "40:23:27": "“Ai de vocês, escribas e fariseus, hipócritas! Porque são como sepulcros caiados, que por fora realmente parecem belos, mas por dentro estão cheios de ossos de mortos e de todo tipo de impureza.", "40:23:28": "Do mesmo modo, por fora vocês parecem justos aos homens, mas por dentro estão cheios de hipocrisia e do que é contra a lei.", "40:23:29": "“Ai de vocês, escribas e fariseus, hipócritas! Porque constroem os sepulcros dos profetas e decoram os túmulos dos justos,", "40:23:30": "e dizem: ‘Se nós tivéssemos vivido nos dias dos nossos antepassados, não teríamos participado com eles em derramar o sangue dos profetas.’", "40:23:31": "Portanto, vocês dão testemunho contra si mesmos de que são filhos daqueles que assassinaram os profetas.", "40:23:32": "Pois bem, completem a medida dos seus antepassados.", "40:23:33": "“Serpentes, descendência de víboras, como fugirão do julgamento da Geena?", "40:23:34": "É por essa razão que eu estou lhes enviando profetas, sábios e instrutores públicos. A alguns deles vocês matarão e pregarão em estacas, e a outros açoitarão nas suas sinagogas e perseguirão de cidade em cidade,", "40:23:35": "para que venha sobre vocês todo o sangue justo derramado na terra, desde o sangue do justo Abel até o sangue de Zacarias, filho de Baraquias, a quem vocês assassinaram entre o santuário e o altar.", "40:23:36": "Eu garanto a vocês: Todas essas coisas virão sobre esta geração.", "40:23:37": "“Jerusalém, Jerusalém, que mata os profetas e apedreja os que lhe são enviados . . . Quantas vezes eu quis ajuntar seus filhos, assim como a galinha ajunta seus pintinhos debaixo das asas! Mas vocês não quiseram.", "40:23:38": "Agora a sua casa ficará abandonada.", "40:23:39": "Pois eu lhes digo: De agora em diante, vocês de modo algum me verão, até que digam: ‘Bendito é aquele que vem em nome de Jeová!’”", "40:24:1": "Quando Jesus estava saindo do templo, seus discípulos se aproximaram para lhe mostrar os edifícios do templo.", "40:24:2": "Em vista disso, ele lhes disse: “Não estão vendo todas estas coisas? Eu lhes digo a verdade: De modo algum ficará aqui pedra sobre pedra sem ser derrubada.”", "40:24:3": "Enquanto ele estava sentado no monte das Oliveiras, os discípulos se aproximaram dele em particular e disseram: “Diga-nos: Quando acontecerão essas coisas e qual será o sinal da sua presença e do final do sistema de coisas?”", "40:24:4": "Jesus, em resposta, lhes disse: “Cuidado para que ninguém os engane,", "40:24:5": "pois muitos virão em meu nome, dizendo: ‘Eu sou o Cristo’, e enganarão a muitos.", "40:24:6": "Vocês ouvirão falar de guerras e notícias de guerras. Cuidado para não ficar apavorados, pois essas coisas têm de acontecer, mas ainda não é o fim.", "40:24:7": "“Porque nação se levantará contra nação e reino contra reino; haverá falta de alimentos e terremotos num lugar após outro.", "40:24:8": "Todas essas coisas são um começo das dores de aflição.", "40:24:9": "“Então as pessoas os entregarão a tribulação e os matarão, e vocês serão odiados por todas as nações, por causa do meu nome.", "40:24:10": "Então, também, muitos tropeçarão, e trairão uns aos outros, e odiarão uns aos outros.", "40:24:11": "Surgirão muitos falsos profetas, que enganarão a muitos;", "40:24:12": "e, por causa do aumento do que é contra a lei, o amor da maioria esfriará.", "40:24:13": "Mas quem perseverar até o fim será salvo.", "40:24:14": "E estas boas novas do Reino serão pregadas em toda a terra habitada, em testemunho a todas as nações, e então virá o fim.", "40:24:15": "“Portanto, quando vocês virem a coisa repugnante que causa desolação, da qual falou Daniel, o profeta, estar num lugar santo (que o leitor use de discernimento),", "40:24:16": "então, os que estiverem na Judeia fujam para os montes.", "40:24:17": "O homem que estiver no terraço não desça para tirar da sua casa os bens,", "40:24:18": "e o homem que estiver no campo não volte para apanhar sua capa.", "40:24:19": "Ai das mulheres grávidas e das que amamentarem naqueles dias!", "40:24:20": "Persistam em orar para que a sua fuga não ocorra no inverno nem no sábado;", "40:24:21": "pois então haverá grande tribulação, como nunca ocorreu desde o princípio do mundo até agora, não, nem ocorrerá de novo.", "40:24:22": "De fato, se não se abreviassem aqueles dias, ninguém seria salvo; mas, por causa dos escolhidos, aqueles dias serão abreviados.", "40:24:23": "“Então, se alguém lhes disser: ‘Vejam! Aqui está o Cristo!’ ou: ‘Ali!’, não acreditem.", "40:24:24": "Porque surgirão falsos cristos e falsos profetas, e farão grandes sinais e milagres a fim de enganar, se possível, até mesmo os escolhidos.", "40:24:25": "Prestem atenção! Eu os avisei antecipadamente.", "40:24:26": "Portanto, se lhes disserem: ‘Vejam, ele está no deserto!’, não saiam; ou: ‘Vejam, ele está no interior da casa!’, não acreditem.", "40:24:27": "Pois, assim como o relâmpago sai do leste e brilha até o oeste, assim será a presença do Filho do Homem.", "40:24:28": "Onde estiver o cadáver, ali se ajuntarão as águias.", "40:24:29": "“Imediatamente depois da tribulação daqueles dias, o sol escurecerá, a lua não dará a sua luz, as estrelas cairão do céu, e os poderes dos céus serão abalados.", "40:24:30": "Então aparecerá no céu o sinal do Filho do Homem, e todas as tribos da terra então baterão no peito, de pesar, e verão o Filho do Homem vir nas nuvens do céu, com poder e grande glória.", "40:24:31": "E ele enviará seus anjos com forte som de trombeta, e eles reunirão os seus escolhidos desde os quatro ventos, de uma extremidade dos céus até a outra extremidade deles.", "40:24:32": "“Aprendam desta ilustração sobre a figueira: assim que os ramos novos ficam tenros e brotam folhas, vocês sabem que o verão está próximo.", "40:24:33": "Do mesmo modo, quando virem todas essas coisas, saibam que ele está próximo, às portas.", "40:24:34": "Eu lhes garanto que esta geração de modo algum passará até que todas essas coisas aconteçam.", "40:24:35": "Céu e terra passarão, mas as minhas palavras de modo algum passarão.", "40:24:36": "“A respeito daquele dia e daquela hora ninguém sabe, nem os anjos dos céus, nem o Filho, mas somente o Pai.", "40:24:37": "Pois, assim como eram os dias de Noé, assim será a presença do Filho do Homem.", "40:24:38": "Porque naqueles dias antes do dilúvio as pessoas comiam e bebiam, os homens se casavam e as mulheres eram dadas em casamento, até o dia em que Noé entrou na arca,", "40:24:39": "e não fizeram caso, até que veio o dilúvio e varreu a todos eles; assim será na presença do Filho do Homem.", "40:24:40": "Dois homens estarão então no campo; um será levado e o outro será abandonado.", "40:24:41": "Duas mulheres estarão moendo no moinho manual; uma será levada e a outra será abandonada.", "40:24:42": "Portanto, mantenham-se vigilantes, porque vocês não sabem em que dia virá o seu Senhor.", "40:24:43": "“Mas entendam isto: se o dono da casa soubesse em que vigília o ladrão viria, ficaria acordado e não permitiria que sua casa fosse arrombada.", "40:24:44": "Por essa razão, vocês também mostrem-se prontos, porque o Filho do Homem vem numa hora que vocês não imaginam.", "40:24:45": "“Quem é realmente o escravo fiel e prudente, a quem o seu senhor encarregou dos seus domésticos, para lhes dar o alimento no tempo apropriado?", "40:24:46": "Feliz aquele escravo se o seu senhor, quando vier, o encontrar fazendo isso!", "40:24:47": "Digo a verdade a vocês: Ele o encarregará de todos os seus bens.", "40:24:48": "“Mas, se aquele escravo mau disser no coração: ‘Meu senhor está demorando’,", "40:24:49": "e começar a espancar seus coescravos, e a comer e beber com os beberrões,", "40:24:50": "o senhor daquele escravo virá num dia em que ele não espera e numa hora que ele não sabe;", "40:24:51": "ele o punirá com a maior severidade e lhe designará um lugar entre os hipócritas. Ali é que haverá o seu choro e o ranger dos seus dentes.", "42:2:1": "Naqueles dias César Augusto emitiu um decreto para que toda a população se registrasse.", "42:2:2": "(Esse primeiro recenseamento ocorreu quando Quirino era governador da Síria.)", "42:2:3": "E todos foram se registrar, cada um na sua própria cidade.", "42:2:4": "Naturalmente, José também subiu da Galileia, da cidade de Nazaré, para a Judeia, à cidade de Davi, que se chama Belém, visto que era membro da casa e família de Davi.", "42:2:5": "Foi se registrar com Maria, que lhe havia sido dada em casamento, conforme prometido, e que já estava perto de dar à luz.", "42:2:6": "Enquanto estavam lá, chegou o tempo de ela dar à luz.", "42:2:7": "E ela deu à luz seu filho primogênito, enrolou-o em panos e o deitou numa manjedoura, porque não havia lugar para eles no alojamento.", "42:2:8": "Havia também na mesma região pastores vivendo ao ar livre e vigiando seus rebanhos à noite.", "42:2:9": "De repente o anjo de Jeová apareceu diante deles, e a glória de Jeová brilhou em volta deles, e eles ficaram com muito medo.", "42:2:10": "Mas o anjo lhes disse: “Não tenham medo, pois estou aqui para lhes declarar boas novas de uma grande alegria que todo o povo terá.", "42:2:11": "Pois hoje lhes nasceu na cidade de Davi um salvador, que é Cristo, o Senhor.", "42:2:12": "E este será o sinal para vocês: acharão um bebê enrolado em panos e deitado numa manjedoura.”", "42:2:13": "De repente, apareceu junto ao anjo uma multidão do exército celestial, louvando a Deus e dizendo:", "42:2:14": "“Glória a Deus nas maiores alturas, e na terra paz entre os homens a quem ele concede o seu favor.”", "42:2:15": "Assim, depois que os anjos se afastaram deles para o céu, os pastores começaram a dizer uns aos outros: “Vamos sem falta a Belém e vejamos o que ocorreu, aquilo que Jeová nos fez saber.”", "42:2:16": "E foram depressa e acharam Maria, bem como José, e o bebê deitado na manjedoura.", "42:2:17": "Quando viram isso, contaram o que lhes havia sido dito a respeito da criancinha.", "42:2:18": "E todos os que ouviram ficaram muito admirados com as coisas que os pastores lhes contaram.", "42:2:19": "Maria, porém, começou a guardar todas essas declarações, tirando conclusões no coração.", "42:2:20": "Os pastores voltaram então, glorificando e louvando a Deus por tudo que tinham ouvido e visto, exatamente como lhes havia sido dito.", "42:2:21": "Depois de oito dias, quando chegou a ocasião de circuncidá-lo, deram-lhe o nome de Jesus, nome dado pelo anjo antes de ele ser concebido.", "42:2:22": "Também, quando chegou o tempo para a purificação deles, segundo a Lei de Moisés, eles o levaram a Jerusalém para apresentá-lo a Jeová,", "42:2:23": "assim como está escrito na Lei de Jeová: “Todo primogênito do sexo masculino tem de ser chamado santo para Jeová.”", "42:2:24": "E ofereceram um sacrifício segundo o que se diz na Lei de Jeová: “Um par de rolas ou dois pombos novos.”", "42:2:25": "Havia em Jerusalém um homem chamado Simeão; esse homem era justo e devoto, e esperava o consolo de Israel, e o espírito santo estava sobre ele.", "42:2:26": "Além disso, ele havia recebido a revelação divina, pelo espírito santo, que ele não veria a morte antes de ver o Cristo de Jeová.", "42:2:27": "Assim, sob o poder do espírito, ele foi ao templo; e quando os pais levaram o menino Jesus para dentro, a fim de lhe fazer o que era o costume segundo a Lei,", "42:2:28": "ele pegou a criança nos braços, louvou a Deus e disse:", "42:2:29": "“Agora, Soberano Senhor, estás deixando o teu escravo ir em paz, segundo a tua declaração,", "42:2:30": "porque meus olhos viram teu meio de salvação,", "42:2:31": "que preparaste à vista de todos os povos,", "42:2:32": "uma luz para remover o véu das nações e uma glória para o teu povo, Israel.”", "42:2:33": "E o pai e a mãe do menino se admiravam das coisas que se falavam dele.", "42:2:34": "Também, Simeão os abençoou e disse a Maria, a mãe do menino: “Escute, este menino será motivo para a queda e para o levantamento de muitos em Israel, e será um sinal contra o qual falar", "42:2:35": "— e, quanto a você, uma longa espada a atravessará —, a fim de que os raciocínios de muitos corações sejam revelados.”", "42:2:36": "Havia também uma profetisa, Ana, filha de Fanuel, da tribo de Aser. Essa mulher era de idade bem avançada e tinha vivido com seu marido por sete anos, desde o seu casamento.", "42:2:37": "Ela era viúva e já tinha 84 anos de idade. Nunca estava ausente do templo, prestando serviço sagrado noite e dia, fazendo jejum e súplicas.", "42:2:38": "Ela se aproximou naquela mesma hora e começou a dar graças a Deus e a falar sobre a criança a todos os que estavam aguardando o livramento de Jerusalém.", "42:2:39": "Assim, quando eles haviam cumprido todas as coisas segundo a Lei de Jeová, voltaram para a Galileia, para sua cidade, Nazaré.", "42:2:40": "E o menino continuou a crescer, ficando forte e cheio de sabedoria; e o favor de Deus continuou sobre ele.", "42:2:41": "De ano em ano, seus pais costumavam ir a Jerusalém para a Festividade da Páscoa.", "42:2:42": "E, quando ele tinha 12 anos de idade, subiram segundo o costume da festividade.", "42:2:43": "Quando a festividade terminou e eles começaram a viagem de volta, o menino Jesus ficou em Jerusalém, mas seus pais não perceberam.", "42:2:44": "Pensando que ele estivesse no grupo que viajava junto, percorreram a distância de um dia e então começaram a procurá-lo entre os parentes e conhecidos.", "42:2:45": "Mas, visto que não o acharam, voltaram a Jerusalém e o procuraram cuidadosamente.", "42:2:46": "Pois bem, depois de três dias, eles o acharam no templo, sentado no meio dos instrutores, escutando-os e fazendo-lhes perguntas.", "42:2:47": "Mas todos os que o escutavam ficavam admirados com o seu entendimento e suas respostas.", "42:2:48": "Assim, seus pais ficaram espantados quando o viram, e sua mãe lhe disse: “Filho, por que você fez isso conosco? Olhe, seu pai e eu estávamos desesperados procurando você.”", "42:2:49": "Mas ele lhes disse: “Por que estavam procurando por mim? Não sabiam que eu devia estar na casa do meu Pai?”", "42:2:50": "No entanto, não compreenderam o que ele estava lhes dizendo.", "42:2:51": "Então ele desceu com eles e voltou a Nazaré, e continuou a estar sujeito a eles. Também, sua mãe guardava cuidadosamente todas essas declarações no coração.", "42:2:52": "E Jesus progredia em sabedoria e em desenvolvimento físico, e no favor de Deus e dos homens.", "45:6:1": "O que diremos então? Continuaremos no pecado para que a bondade imerecida aumente?", "45:6:2": "Certamente que não! Visto que morremos com relação ao pecado, como podemos ainda continuar vivendo nele?", "45:6:3": "Ou vocês não sabem que todos nós, que fomos batizados em Cristo Jesus, fomos batizados na sua morte?", "45:6:4": "Portanto, fomos sepultados com ele por meio do nosso batismo na sua morte, a fim de que, assim como Cristo foi levantado dentre os mortos por meio do poder glorioso do Pai, assim também nós vivamos uma vida nova.", "45:6:5": "Se fomos unidos a ele na semelhança da sua morte, certamente seremos também unidos a ele na semelhança da sua ressurreição.", "45:6:6": "Pois sabemos que a nossa velha personalidade foi pregada na estaca junto com ele a fim de que o nosso corpo pecaminoso perdesse seu poder, de modo que não fôssemos mais escravos do pecado.", "45:6:7": "Pois quem morreu foi absolvido do seu pecado.", "45:6:8": "Além do mais, se morremos com Cristo, cremos que também viveremos com ele.", "45:6:9": "Pois sabemos que, agora que foi levantado dentre os mortos, Cristo não morre mais; a morte não domina mais sobre ele.", "45:6:10": "Pois a morte que ele morreu, ele morreu de uma vez para sempre com relação ao pecado, mas a vida que ele vive, ele vive com relação a Deus.", "45:6:11": "Assim também vocês, considerem-se mortos com relação ao pecado, mas vivos com relação a Deus, por meio de Cristo Jesus.", "45:6:12": "Portanto, não deixem que o pecado continue a reinar em seus corpos mortais, fazendo com que vocês obedeçam aos seus desejos.", "45:6:13": "Nem continuem a apresentar os seus corpos ao pecado como armas da injustiça, mas apresentem-se a Deus como pessoas que passaram da morte para a vida; apresentem também os seus corpos a Deus como armas da justiça.", "45:6:14": "Pois o pecado não deve dominar sobre vocês, visto que vocês não estão debaixo de lei, mas debaixo de bondade imerecida.", "45:6:15": "O que concluímos então? Cometeremos pecado, já que não estamos debaixo de lei, mas debaixo de bondade imerecida? Certamente que não!", "45:6:16": "Não sabem que, se vocês se apresentam a alguém como escravos, para lhe obedecer, são escravos daquele a quem obedecem — quer do pecado, que leva à morte, quer da obediência, que leva à justiça?", "45:6:17": "Mas graças sejam dadas a Deus, pois, embora no passado vocês tenham sido escravos do pecado, tornaram-se obedientes de coração ao padrão de ensinamento a que foram entregues.", "45:6:18": "Sim, uma vez que foram libertados do pecado, vocês se tornaram escravos da justiça.", "45:6:19": "Estou falando em termos humanos por causa da fraqueza da sua carne; pois, assim como vocês apresentaram os seus membros como escravos à impureza e ao que é contra a lei, resultando no que é contra a lei, apresentem agora os seus membros como escravos à justiça, o que levará à santidade.", "45:6:20": "Pois, quando vocês eram escravos do pecado, estavam livres com respeito à justiça.", "45:6:21": "Quais eram então os frutos que vocês produziam naquele tempo? Coisas das quais se envergonham agora. Pois o fim dessas coisas é a morte.", "45:6:22": "No entanto, agora que foram libertados do pecado e se tornaram escravos de Deus, o fruto que estão produzindo é a santidade, e o fim será a vida eterna.", "45:6:23": "Pois o salário pago pelo pecado é a morte, mas a dádiva que Deus dá é a vida eterna por Cristo Jesus, nosso Senhor.", "47:2:1": "Pois eu decidi que a minha próxima visita a vocês não será triste.", "47:2:2": "Porque, se eu os entristecer, quem haverá para me alegrar, a não ser aqueles que eu tiver entristecido?", "47:2:3": "Escrevi o que escrevi para que, quando eu for aí, não fique triste por causa daqueles que deveriam me alegrar; porque tenho confiança de que o que me traz alegria traz a mesma alegria a todos vocês.", "47:2:4": "Pois eu lhes escrevi com muita aflição e angústia de coração, com muitas lágrimas, não para entristecê-los, mas para que soubessem do profundo amor que tenho por vocês.", "47:2:5": "Ora, se alguém causou tristeza, ele entristeceu não a mim, mas a todos vocês, até certo ponto — para não ser severo demais no que digo.", "47:2:6": "Essa censura da parte da maioria é suficiente para esse homem;", "47:2:7": "agora, ao contrário, vocês devem perdoá-lo bondosamente e consolá-lo, para que ele não seja vencido pela excessiva tristeza.", "47:2:8": "Eu os exorto, portanto, a reafirmar o seu amor por ele.", "47:2:9": "Pois é também por isso que lhes escrevi: para ver se vocês dariam provas de que são obedientes em todas as coisas.", "47:2:10": "Se vocês perdoarem alguém por alguma coisa, eu também perdoo. De fato, o que perdoei (se eu tiver perdoado alguma coisa), foi para o bem de vocês, à vista de Cristo,", "47:2:11": "para que não sejamos vencidos por Satanás, pois não desconhecemos as suas tramas.", "47:2:12": "Quando cheguei a Trôade para declarar as boas novas a respeito do Cristo, e foi aberta para mim uma porta na obra do Senhor,", "47:2:13": "meu espírito não teve alívio porque não achei Tito, meu irmão. Então me despedi dos irmãos dali e parti para a Macedônia.", "47:2:14": "Mas graças sejam dadas a Deus, que sempre nos conduz num desfile triunfal em companhia do Cristo e, por nosso intermédio, espalha o aroma do conhecimento dele por toda a parte!", "47:2:15": "Pois para Deus somos aroma agradável de Cristo, entre os que estão a caminho da salvação e entre os que estão a caminho da destruição", "47:2:16": "— para estes últimos, cheiro de morte que leva à morte; para os primeiros, aroma de vida que leva à vida. E quem está qualificado para isso?", "47:2:17": "Nós estamos, pois não somos vendedores ambulantes da palavra de Deus, como muitos são, mas falamos com toda a sinceridade como enviados por Deus, sim, à vista de Deus e na companhia de Cristo.", "50:2:1": "Se há, pois, algum encorajamento em Cristo, algum consolo de amor, algum companheirismo espiritual, algum terno sentimento e compaixão,", "50:2:2": "tornem plena a minha alegria por terem o mesmo modo de pensar e o mesmo amor, sendo plenamente unidos, tendo o mesmo pensamento.", "50:2:3": "Não façam nada por rivalidade nem por presunção; mas, com humildade, considerem os outros superiores a vocês,", "50:2:4": "buscando não somente os seus próprios interesses, mas também os interesses dos outros.", "50:2:5": "Mantenham a mesma atitude que Cristo Jesus teve:", "50:2:6": "embora ele existisse em forma de Deus, nem mesmo chegou a pensar na ideia de tentar ser igual a Deus.", "50:2:7": "Pelo contrário, ele abriu mão de tudo que tinha, assumiu a forma de escravo e se tornou humano.", "50:2:8": "Mais do que isso, quando veio como homem, ele se humilhou e se tornou obediente a ponto de enfrentar a morte, sim, morte numa estaca.", "50:2:9": "Por essa razão, Deus o enalteceu a uma posição superior e lhe deu bondosamente o nome que está acima de todo outro nome,", "50:2:10": "a fim de que, diante do nome de Jesus, se dobre todo joelho — dos que estão no céu, na terra e debaixo do chão —", "50:2:11": "e toda língua reconheça abertamente que Jesus Cristo é Senhor, para a glória de Deus, o Pai.", "50:2:12": "Portanto, meus amados, assim como vocês sempre obedeceram, não somente durante a minha presença, porém com muito mais prontidão agora durante a minha ausência, persistam em produzir a sua própria salvação com temor e tremor.", "50:2:13": "Pois Deus é aquele que, segundo o que lhe agrada, está agindo em vocês, e lhes dá tanto o desejo como o poder de agir.", "50:2:14": "Continuem fazendo todas as coisas sem queixas nem discussões,", "50:2:15": "para que venham a ser irrepreensíveis e inocentes, filhos de Deus sem defeito no meio de uma geração pervertida e corrompida, no meio da qual vocês estão brilhando como iluminadores no mundo,", "50:2:16": "mantendo-se firmemente agarrados à palavra da vida. Então terei motivo para me alegrar no dia de Cristo, por saber que eu não corri em vão nem me esforcei tanto em vão.", "50:2:17": "Contudo, mesmo que eu esteja sendo derramado como oferta de bebida sobre o sacrifício e o serviço sagrado que provém da sua fé, me alegro e compartilho a minha alegria com todos vocês.", "50:2:18": "Do mesmo modo, vocês também devem se alegrar e compartilhar a sua alegria comigo.", "50:2:19": "Espero no Senhor Jesus lhes enviar em breve Timóteo, para que eu fique encorajado ao receber notícias de vocês.", "50:2:20": "Pois não tenho a nenhum outro de disposição igual à dele, que cuidará genuinamente de vocês.", "50:2:21": "Pois todos os outros estão buscando os seus próprios interesses, não os de Jesus Cristo.", "50:2:22": "Mas vocês conhecem a prova que ele deu de si mesmo: ele trabalhou como escravo comigo na promoção das boas novas, como um filho junto ao pai.", "50:2:23": "Portanto, é a ele que espero enviar assim que eu souber o que vai acontecer comigo.", "50:2:24": "De fato, estou confiante no Senhor em que eu mesmo irei também em breve.", "50:2:25": "Mas, no momento, acho necessário lhes enviar Epafrodito, meu irmão, colaborador e companheiro de batalha, aquele que vocês enviaram para servir às minhas necessidades pessoais,", "50:2:26": "visto que ele deseja muito ver a todos vocês e está deprimido por terem ouvido que ele ficou doente.", "50:2:27": "De fato, ele adoeceu quase a ponto de morrer. Mas Deus teve misericórdia dele; na verdade, não só dele, mas também de mim, para que eu não tivesse uma tristeza após outra.", "50:2:28": "Por isso eu o envio com a maior urgência, para que, quando o virem, vocês se alegrem novamente, e eu fique menos ansioso.", "50:2:29": "Portanto, acolham-no como é de costume no Senhor, com toda a alegria, e continuem a prezar homens como ele,", "50:2:30": "porque ele quase morreu por causa da obra de Cristo, arriscando a vida para compensar o fato de que vocês não estavam aqui para prestar serviço a mim.", "62:5:1": "Quem crê que Jesus é o Cristo nasceu de Deus. E quem ama aquele que causou o nascimento ama também aquele que nasceu dele.", "62:5:2": "Por meio disto sabemos que amamos os filhos de Deus, quando amamos a Deus e cumprimos os seus mandamentos.", "62:5:3": "Pois o amor a Deus significa o seguinte: que obedeçamos aos seus mandamentos; contudo, os seus mandamentos não são pesados,", "62:5:4": "porque todo aquele que nasceu de Deus vence o mundo. E esta é a vitória que venceu o mundo: a nossa fé.", "62:5:5": "Quem pode vencer o mundo? Não é aquele que tem fé em que Jesus é o Filho de Deus?", "62:5:6": "Este é aquele que veio por meio de água e de sangue: Jesus Cristo; não apenas com a água, mas com a água e com o sangue. E o espírito dá testemunho, porque o espírito é a verdade.", "62:5:7": "Pois são três os que dão testemunho:", "62:5:8": "o espírito, a água e o sangue; e os três estão de acordo.", "62:5:9": "Se aceitamos o testemunho de homens, maior é o testemunho de Deus. Porque este é o testemunho de Deus: o testemunho que ele deu a respeito do seu Filho.", "62:5:10": "Quem deposita fé no Filho de Deus tem o testemunho dentro de si. Quem não tem fé em Deus faz dele um mentiroso, porque não deposita fé no testemunho dado por Deus a respeito do seu Filho.", "62:5:11": "E este é o testemunho: Deus nos deu vida eterna, e essa vida está em seu Filho.", "62:5:12": "Quem tem o Filho tem essa vida; quem não tem o Filho de Deus não tem essa vida.", "62:5:13": "Eu lhes escrevo estas coisas para que vocês, que depositaram fé no nome do Filho de Deus, saibam que têm vida eterna.", "62:5:14": "E esta é a confiança que temos nele: não importa o que peçamos segundo a sua vontade, ele nos ouve.", "62:5:15": "E, se sabemos que ele nos ouve com respeito àquilo que pedimos, sabemos que teremos as coisas pedidas, visto que as pedimos a ele.", "62:5:16": "Se alguém vir seu irmão cometendo um pecado que não incorre em morte, ele pedirá, e Deus lhe dará vida, sim, aos que não cometerem um pecado que incorre em morte. Há um pecado que incorre em morte. Não é a respeito desse pecado que eu digo que ele deve orar.", "62:5:17": "Toda injustiça é pecado; contudo, há um pecado que não incorre em morte.", "62:5:18": "Sabemos que todo aquele que nasceu de Deus não pratica o pecado, mas aquele que nasceu de Deus vigia sobre ele, e o Maligno não pode pôr as mãos nele.", "62:5:19": "Sabemos que nos originamos de Deus, mas o mundo inteiro está no poder do Maligno.", "62:5:20": "E sabemos que o Filho de Deus veio e nos deu entendimento para podermos obter conhecimento daquele que é verdadeiro. E nós estamos em união com aquele que é verdadeiro, por meio do seu Filho, Jesus Cristo. Esse é o verdadeiro Deus e a vida eterna.", "62:5:21": "Filhinhos, guardem-se dos ídolos.", "66:16:1": "Ouvi então uma voz alta sair do santuário e dizer aos sete anjos: “Vão e derramem sobre a terra as sete tigelas da ira de Deus.”", "66:16:2": "O primeiro foi e derramou a sua tigela sobre a terra. E uma úlcera nociva e maligna afligiu as pessoas que tinham a marca da fera e adoravam a sua imagem.", "66:16:3": "O segundo derramou a sua tigela no mar. E o mar se transformou em sangue como de um morto, e morreu toda criatura vivente que havia no mar.", "66:16:4": "O terceiro derramou a sua tigela nos rios e nas fontes de água. E eles se transformaram em sangue.", "66:16:5": "Eu ouvi o anjo responsável pelas águas dizer: “Tu, Aquele que é e que era, o Leal, és justo, pois decretaste esses julgamentos,", "66:16:6": "pois eles derramaram o sangue dos santos e dos profetas, e tu lhes deste sangue para beber; isso é o que merecem.”", "66:16:7": "E eu ouvi o altar dizer: “Sim, Jeová Deus, o Todo-Poderoso, verdadeiros e justos são os teus julgamentos.”", "66:16:8": "O quarto derramou a sua tigela sobre o sol. E foi concedido ao sol abrasar as pessoas com fogo.", "66:16:9": "As pessoas foram então abrasadas pelo grande calor, mas elas blasfemaram contra o nome de Deus, que tem a autoridade sobre essas pragas, e não se arrependeram nem lhe deram glória.", "66:16:10": "O quinto derramou a sua tigela sobre o trono da fera. E o reino dela ficou em escuridão, e as pessoas começaram a morder a língua de dor,", "66:16:11": "mas blasfemaram contra o Deus do céu por causa das suas dores e das suas úlceras, e não se arrependeram das suas obras.", "66:16:12": "O sexto derramou a sua tigela sobre o grande rio Eufrates. E a água dele secou, a fim de que se preparasse o caminho para os reis do nascente do sol.", "66:16:13": "E vi três expressões inspiradas impuras, parecidas com rãs, sair da boca do dragão, da boca da fera e da boca do falso profeta.", "66:16:14": "De fato, são expressões inspiradas por demônios e realizam sinais; vão aos reis de toda a terra habitada, a fim de reuni-los para a guerra do grande dia de Deus, o Todo-Poderoso.", "66:16:15": "“Escute: Venho como um ladrão. Feliz aquele que fica desperto e conserva consigo as suas roupas, para que não ande nu e as pessoas não olhem para a sua vergonha.”", "66:16:16": "E elas os reuniram no lugar que em hebraico se chama Armagedom.", "66:16:17": "O sétimo derramou a sua tigela no ar. Então, uma voz alta saiu do santuário, desde o trono, dizendo: “Está feito!”", "66:16:18": "E houve relâmpagos, vozes e trovões, e houve um grande terremoto, diferente de todos que já tinham ocorrido desde que os homens vieram a existir na terra, de tão extenso e tão grande que foi o terremoto.", "66:16:19": "A grande cidade se fendeu em três partes, e as cidades das nações caíram. E Deus se lembrou de Babilônia, a Grande, para lhe dar o cálice com o vinho do furor da sua ira.", "66:16:20": "Também, todas as ilhas fugiram, e os montes desapareceram.", "66:16:21": "Então grandes pedras de granizo, cada uma do peso de cerca de um talento, caíram do céu sobre as pessoas, e as pessoas blasfemaram contra Deus por causa da praga de granizo, pois a praga era extraordinariamente grande."}};
